void Window::DoRevertFile() {
    auto* pDoc = GetActiveDoc();
    if (pDoc && !pDoc->filePath.empty() && std::filesystem::exists(pDoc->filePath)) {
        pDoc->buffer.LoadFromFile(pDoc->filePath);
        pDoc->originalDiskText = pDoc->buffer.GetText();
        pDoc->isDirty = false;
        pDoc->hasExternalDiskConflict = false;
        std::error_code writeEc;
        pDoc->lastDiskWriteTime = std::filesystem::last_write_time(pDoc->filePath, writeEc);
        pDoc->hasLastDiskWriteTime = !writeEc;
        pDoc->diagnostics = editor::SyntaxValidator::Validate(pDoc->filePath, pDoc->buffer);
        RunExtraDocDiagnostics(*pDoc, pDoc->diagnostics);
        if (pDoc->isDiffView) ComputeDiffHunks(*pDoc);
        if (m_lsp.IsRunning()) {
            m_lsp.NotifyDidChange(pDoc->filePath, pDoc->originalDiskText);
        }
        UpdateDrawerDirtyFiles();
        UpdateDrawerErrorFiles();
        InvalidateRect(m_hwnd, nullptr, FALSE);
    }
}

void Window::DoCloseEditor() {
    if (ShouldAutoSaveOnFocusChange()) {
        FlushPendingAutoSaves();
    }
    auto& group = GetActiveGroup();
    if (group.activeDocIdx >= 0) {
        CloseDocument(m_focusedGroupIdx, group.activeDocIdx);
    }
}

void Window::DoCloseFolder() {
    m_drawer.CloseFolder();
    m_symbolIndex.Clear();
    m_navBackStack.clear();
    m_navForwardStack.clear();
    m_persistedBookmarks.clear();
    m_cachedWorkspaceDir = L"";
    m_cachedProjectRuntimeId = L"";
    m_currentStatusBarRuntimeId = L"";
    m_drawer.RefreshGitState(true);
    m_editor.GetPackageManagerView().ScanInstalledPackages(L"");
    m_lastLaunchCheckTick = 0;
    m_lastGitStatCheckTick = 0;
    UpdateDrawerErrorFiles();
    UpdateExecutionButtonStates();
    SaveSessionState();
    RunManualGarbageCollection(false);
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoReopenClosedEditor() {
    std::error_code ec;
    while (!m_closedTabHistory.empty()) {
        ClosedTabEntry entry = std::move(m_closedTabHistory.back());
        m_closedTabHistory.pop_back();
        if (entry.filePath.empty() || !std::filesystem::exists(entry.filePath, ec)) {
            continue;
        }
        if (m_editorGroups.empty()) {
            m_editorGroups.push_back(editor::EditorGroup{});
        }
        int maxGrp = static_cast<int>(m_editorGroups.size()) - 1;
        m_focusedGroupIdx = (std::clamp)(entry.groupIdx, 0, maxGrp);
        OpenFileDocument(entry.filePath, false);
        if (auto* pDoc = GetActiveDoc()) {
            size_t lineCount = pDoc->buffer.GetLineCount();
            size_t clampedLine = (lineCount > 0) ? (std::min)(entry.cursorLine, lineCount - 1) : 0;
            pDoc->buffer.SetCursor(clampedLine, entry.cursorCol);
            pDoc->scrollLine = (lineCount > 0) ? (std::min)(entry.scrollLine, lineCount - 1) : 0;
            pDoc->scrollOffsetX = (std::max)(0.0f, entry.scrollOffsetX);
            EnsureCursorVisible();
            InvalidateRect(m_hwnd, nullptr, FALSE);
        }
        return;
    }
}

void Window::SyncDocumentBuffers(editor::OpenDocument* sourceDoc) {
    if (!sourceDoc || sourceDoc->filePath.empty() || sourceDoc->isSpecialView) return;
    bool hasDuplicateTab = false;
    auto checkGroups = [&](const std::vector<editor::EditorGroup>& groups) {
        for (const auto& group : groups) {
            for (const auto& doc : group.docs) {
                if (&doc != sourceDoc && !doc.filePath.empty() && _wcsicmp(doc.filePath.c_str(), sourceDoc->filePath.c_str()) == 0) {
                    hasDuplicateTab = true;
                    return;
                }
            }
        }
    };
    checkGroups(m_editorGroups);
    if (!hasDuplicateTab) {
        for (const auto& fw : m_floatingWindows) {
            if (fw && fw->kind == FloatingDockKind::EditorGroup) {
                checkGroups(fw->editorGroups);
                if (hasDuplicateTab) break;
            }
        }
    }
    if (!hasDuplicateTab) return;

    std::wstring text = sourceDoc->buffer.GetText();
    auto syncGroups = [&](std::vector<editor::EditorGroup>& groups) {
        for (auto& group : groups) {
            for (auto& doc : group.docs) {
                if (&doc != sourceDoc && !doc.filePath.empty() && _wcsicmp(doc.filePath.c_str(), sourceDoc->filePath.c_str()) == 0) {
                    if (doc.buffer.GetText() != text) {
                        doc.buffer.SetText(text);
                    }
                    doc.isDirty = sourceDoc->isDirty;
                    if (!sourceDoc->isDirty) {
                        doc.originalDiskText = sourceDoc->originalDiskText;
                        doc.lastDiskWriteTime = sourceDoc->lastDiskWriteTime;
                        doc.hasLastDiskWriteTime = sourceDoc->hasLastDiskWriteTime;
                        doc.hasExternalDiskConflict = false;
                    }
                    if (doc.isDiffView) {
                        ComputeDiffHunks(doc);
                    }
                }
            }
        }
    };
    syncGroups(m_editorGroups);
    for (auto& fw : m_floatingWindows) {
        if (fw && fw->kind == FloatingDockKind::EditorGroup) {
            syncGroups(fw->editorGroups);
        }
    }
}

void Window::UpdateDrawerDirtyFiles() {
    std::wstring root = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L"";
    if (root.empty()) {
        m_drawer.SetDirtyFiles({});
        return;
    }
    while (!root.empty() && (root.back() == L'\\' || root.back() == L'/')) {
        root.pop_back();
    }
    std::wstring normRoot = root;
    for (auto& c : normRoot) if (c == L'/') c = L'\\';

    std::vector<std::wstring> dirtyPaths;
    auto collectDirty = [&](const std::vector<editor::EditorGroup>& groups) {
        for (const auto& group : groups) {
            for (const auto& doc : group.docs) {
                // Must have a real file on disk and not be virtual/special/untitled
                if (doc.filePath.empty() || doc.isSpecialView) continue;
                if (doc.fileName.rfind(L"Untitled", 0) == 0 || doc.filePath.rfind(L"Untitled", 0) == 0) continue;

                // Must strictly reside inside the workspace project folder
                std::wstring normPath = doc.filePath;
                for (auto& c : normPath) if (c == L'/') c = L'\\';

                if (normPath.length() <= normRoot.length() + 1 ||
                    _wcsnicmp(normPath.c_str(), normRoot.c_str(), normRoot.length()) != 0 ||
                    normPath[normRoot.length()] != L'\\') {
                    continue; // Outside project folder, never track in Git
                }

                // Never track internal IDE or git metadata files
                std::wstring rel = normPath.substr(normRoot.length() + 1);
                if (rel == L".git" || rel.rfind(L".git\\", 0) == 0 ||
                    rel == L".phide" || rel.rfind(L".phide\\", 0) == 0) {
                    continue;
                }

                if (doc.isDirty) {
                    if (doc.isDiffView && doc.diffHunks.empty()) continue;
                    if (!doc.isDiffView && !doc.originalDiskText.empty() && doc.buffer.GetText() == doc.originalDiskText) continue;
                    dirtyPaths.push_back(doc.filePath);
                }
            }
        }
    };
    collectDirty(m_editorGroups);
    for (const auto& fw : m_floatingWindows) {
        if (fw && fw->kind == FloatingDockKind::EditorGroup) {
            collectDirty(fw->editorGroups);
        }
    }
    m_drawer.SetDirtyFiles(dirtyPaths);
}

void Window::UpdateDrawerErrorFiles() {
    std::map<std::wstring, size_t> errorFiles;
    auto collectErrors = [&](const std::vector<editor::EditorGroup>& groups) {
        for (const auto& group : groups) {
            for (const auto& doc : group.docs) {
                if (!doc.diagnostics.empty() && !doc.isSpecialView) {
                    size_t actionableCount = 0;
                    for (const auto& d : doc.diagnostics) {
                        if (!d.isUnnecessary && d.severity <= 2) ++actionableCount;
                    }
                    std::wstring key = !doc.filePath.empty() ? doc.filePath : doc.fileName;
                    if (!key.empty() && actionableCount > 0) {
                        errorFiles[key] = actionableCount;
                    }
                }
            }
        }
    };
    collectErrors(m_editorGroups);
    for (const auto& fw : m_floatingWindows) {
        if (fw && fw->kind == FloatingDockKind::EditorGroup) {
            collectErrors(fw->editorGroups);
        }
    }
    m_drawer.SetErrorFiles(errorFiles);
    RebuildProblemsCache();
}

bool Window::IsCursorInComment(const editor::OpenDocument* pDoc) const {
    if (!pDoc || pDoc->isSpecialView || pDoc->isImageView || pDoc->isUnsupportedBinary) return false;
    auto curPos = pDoc->buffer.GetCursor();
    if (curPos.line >= pDoc->buffer.GetLineCount()) return false;

    std::wstring docExt;
    std::wstring fn = pDoc->filePath.empty() ? pDoc->fileName : pDoc->filePath;
    auto dotPos = fn.rfind(L'.');
    if (dotPos != std::wstring::npos) docExt = fn.substr(dotPos);
    for (auto& c : docExt) c = static_cast<wchar_t>(towlower(c));

    // 1. Check syntax tokens from buffer lexer
    auto tokens = pDoc->buffer.GetTokensForLine(curPos.line, docExt);
    for (const auto& tok : tokens) {
        if (tok.type == editor::TokenType::Comment) {
            if (curPos.col >= tok.startCol && curPos.col <= tok.startCol + tok.length) {
                return true;
            }
        }
    }

    // 2. Fallback lexical scan for comments currently being typed
    const auto& lineText = pDoc->buffer.GetLine(curPos.line);
    bool isPython = (docExt == L".py" || docExt == L".pyw" || docExt == L"py");
    bool isPhp = (docExt == L".php" || docExt == L"php");
    bool isShellOrYaml = (docExt == L".sh" || docExt == L".bash" || docExt == L".zsh" || docExt == L".yaml" || docExt == L".yml" || docExt == L".toml" || docExt == L".ini" || docExt == L".env");

    bool inDblQuote = false;
    bool inSglQuote = false;
    for (size_t i = 0; i < lineText.length() && i < curPos.col; ++i) {
        wchar_t c = lineText[i];
        if (c == L'\\' && (inDblQuote || inSglQuote) && i + 1 < lineText.length()) { ++i; continue; }
        if (c == L'"' && !inSglQuote) inDblQuote = !inDblQuote;
        else if (c == L'\'' && !inDblQuote) inSglQuote = !inSglQuote;
        else if (!inDblQuote && !inSglQuote) {
            if (isPython || isShellOrYaml) {
                if (c == L'#') return true;
            } else if (isPhp) {
                if (c == L'#' || (c == L'/' && i + 1 < lineText.length() && lineText[i + 1] == L'/')) return true;
            } else {
                if (c == L'/' && i + 1 < lineText.length() && lineText[i + 1] == L'/') return true;
            }
        }
    }

    size_t firstNonWs = lineText.find_first_not_of(L" \t");
    if (firstNonWs != std::wstring::npos && firstNonWs < curPos.col) {
        if (isPython || isShellOrYaml) {
            if (lineText[firstNonWs] == L'#') return true;
        } else if (isPhp) {
            if (lineText[firstNonWs] == L'#' || lineText.substr(firstNonWs, 2) == L"//" || lineText.substr(firstNonWs, 2) == L"/*" || lineText[firstNonWs] == L'*') return true;
        } else {
            if (lineText.substr(firstNonWs, 2) == L"//" || lineText.substr(firstNonWs, 2) == L"/*" || lineText[firstNonWs] == L'*') return true;
        }
    }

    return false;
}

void Window::UpdatePrediction() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView || pDoc->isImageView || pDoc->isUnsupportedBinary || pDoc->HasSelection() || IsCursorInComment(pDoc)) {
        m_editor.ClearPrediction();
        return;
    }
    auto cursor = pDoc->buffer.GetCursor();
    std::vector<std::wstring> openFiles;
    for (const auto& group : m_editorGroups) {
        for (const auto& d : group.docs) {
            if (!d.filePath.empty()) openFiles.push_back(d.filePath);
        }
    }
    std::wstring path = pDoc->filePath.empty() ? pDoc->fileName : pDoc->filePath;
    auto pred = m_predictionEngine.PredictNextEdit(path, pDoc->buffer, cursor.line, cursor.col, openFiles);
    if (pred.isValid) {
        m_editor.SetPrediction(pred);
    } else {
        m_editor.ClearPrediction();
    }
}

void Window::CommitAutocompleteSelection() {
    const auto* rawItem = m_editor.GetSelectedAutocompleteItem();
    auto* pDoc = GetActiveDoc();
    if (!rawItem || !pDoc) {
        m_editor.DismissAutocomplete();
        m_editor.ClearGhostText();
        return;
    }

    editor::IntelliSenseItem selectedItem = *rawItem;
    const auto* item = &selectedItem;

    // Adaptively learn user's chosen symbol and sequence transition (0ms freeze)
    std::wstring docExt;
    std::wstring fn = pDoc->fileName.empty() ? pDoc->filePath : pDoc->fileName;
    auto dotPos = fn.rfind(L'.');
    if (dotPos != std::wstring::npos) docExt = fn.substr(dotPos + 1);
    for (auto& c : docExt) c = towlower(c);
    m_adaptiveEngine.RecordSymbolUsage(item->label, docExt);

    m_suppressNextChar = true;
    auto pos = pDoc->buffer.GetCursor();
    const auto& lineText = pDoc->buffer.GetLine(pos.line);
    std::wstring prefix = editor::IntelliSenseEngine::ExtractQueryPrefix(lineText, pos.col);

    // 0a. Completing an NPM package name inside quotes (e.g. from 'luc|' -> from 'lucide-react')
    if (item->origin == L"npm-module") {
        size_t lastQuote = lineText.find_last_of(L"\"'`", pos.col > 0 ? pos.col - 1 : 0);
        size_t charsToDel = (lastQuote != std::wstring::npos && pos.col > lastQuote) ? (pos.col - lastQuote - 1) : prefix.length();
        for (size_t i = 0; i < charsToDel; ++i) {
            pDoc->buffer.Backspace();
        }
        for (wchar_t c : item->insertText) {
            pDoc->buffer.InsertChar(c);
        }
        MarkDocumentModified(pDoc);
        m_editor.DismissAutocomplete();
        m_editor.ClearGhostText();
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }

    // 0b. Check if completing a file or directory path (Images 2 & 3)
    if (item->origin == L"path" || item->kind == editor::CompletionKind::Folder || item->kind == editor::CompletionKind::File) {
        size_t lastSep = lineText.find_last_of(L"/\\\"'`", pos.col > 0 ? pos.col - 1 : 0);
        size_t charsToDel = (lastSep != std::wstring::npos && pos.col > lastSep) ? (pos.col - lastSep - 1) : 0;
        for (size_t i = 0; i < charsToDel; ++i) {
            pDoc->buffer.Backspace();
        }
        for (wchar_t c : item->insertText) {
            pDoc->buffer.InsertChar(c);
        }
        MarkDocumentModified(pDoc);

        // If completed a folder, immediately trigger sub-directory completion!
        if (item->kind == editor::CompletionKind::Folder || item->insertText.ends_with(L"/")) {
            auto newPos = pDoc->buffer.GetCursor();
            const auto& newLine = pDoc->buffer.GetLine(newPos.line);
            std::wstring docTarget = pDoc->filePath.empty() ? pDoc->fileName : pDoc->filePath;
            if (m_drawer.HasOpenFolder()) {
                m_intelliSense.SetWorkspaceRoot(m_drawer.GetOpenFolderPath());
                m_editor.SetWorkspaceRoot(m_drawer.GetOpenFolderPath());
            }
            auto subItems = m_intelliSense.QueryCompletions(docTarget, newLine, newPos.col, pDoc ? &pDoc->buffer.GetLines() : nullptr);
            if (!subItems.empty()) {
                m_editor.ShowAutocomplete(subItems);
            } else {
                m_editor.DismissAutocomplete();
                m_editor.ClearGhostText();
            }
        } else {
            m_editor.DismissAutocomplete();
            m_editor.ClearGhostText();
        }
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }

    // Check if user is completing an Emmet abbreviation or a snippet (e.g. "div.hello", "!", "html:5", "clg")
    if (item->origin == L"emmet" || item->kind == editor::CompletionKind::Snippet) {
        std::wstring ext;
        std::wstring fn = pDoc->fileName.empty() ? pDoc->filePath : pDoc->fileName;
        auto dotPos = fn.rfind(L'.');
        if (dotPos != std::wstring::npos) ext = fn.substr(dotPos + 1);
        for (auto& c : ext) c = towlower(c);

        if (item->origin == L"emmet") {
            if (pDoc->buffer.ExpandEmmet(ext)) {
                MarkDocumentModified(pDoc);
                m_editor.DismissAutocomplete();
                m_editor.ClearGhostText();
                InvalidateRect(m_hwnd, nullptr, FALSE);
                return;
            }
        }

        const auto* pSnip = m_snippetManager.FindSnippetByPrefix(item->label, ext);
        if (pSnip) {
            size_t replaceLen = prefix.length();
            size_t pStart = (pos.col >= prefix.length()) ? (pos.col - prefix.length()) : 0;
            if (!pSnip->body.empty() && pSnip->body[0].rfind(L"<?", 0) == 0 &&
                pStart >= 2 && lineText[pStart - 2] == L'<' && lineText[pStart - 1] == L'?') {
                replaceLen += 2;
            }
            m_snippetManager.ExpandSnippet(*pSnip, pDoc->buffer, replaceLen, fn);
            EnsureAutoImportAndUseClient(pDoc, L"");
            MarkDocumentModified(pDoc);
            m_editor.DismissAutocomplete();
            m_editor.ClearGhostText();
            InvalidateRect(m_hwnd, nullptr, FALSE);
            return;
        }
    }

    // Check if user is completing an HTML tag or JSX Component tag (e.g. typed "<div", "<Camera", "</main", or "div")
    bool isTagKind = (item->kind == editor::CompletionKind::Tag);
    size_t prefixStart = (pos.col >= prefix.length()) ? (pos.col - prefix.length()) : 0;
    bool hasClosingAngle = (prefixStart >= 2 && lineText[prefixStart - 1] == L'/' && lineText[prefixStart - 2] == L'<');
    bool hasLeadingAngle = (!hasClosingAngle && prefixStart > 0 && lineText[prefixStart - 1] == L'<');

    static const std::unordered_set<std::wstring> voidTags = {
        L"area", L"base", L"br", L"col", L"embed", L"hr", L"img", L"input",
        L"link", L"meta", L"param", L"source", L"track", L"wbr"
    };

    std::wstring tagLower = item->label;
    for (auto& c : tagLower) c = towlower(c);
    bool isVoid = (voidTags.count(tagLower) > 0);
    bool isReactComponentTag = hasLeadingAngle && !item->label.empty() && iswupper(item->label[0]);

    if (isTagKind || hasLeadingAngle || hasClosingAngle) {
        // Tag completion
        for (size_t i = 0; i < prefix.length(); ++i) {
            pDoc->buffer.Backspace();
        }

        if (hasClosingAngle) {
            // Already typed '</' (closing tag): Complete with 'tag>' ONLY (avoid duplicate '>' if already present after cursor)
            auto curPosClose = pDoc->buffer.GetCursor();
            const auto& curLineClose = pDoc->buffer.GetLine(curPosClose.line);
            bool hasTrailingGt = (curPosClose.col < curLineClose.length() && curLineClose[curPosClose.col] == L'>');
            std::wstring closePart = hasTrailingGt ? item->label : (item->label + L">");
            for (wchar_t c : closePart) pDoc->buffer.InsertChar(c);
            if (hasTrailingGt) {
                auto endP = pDoc->buffer.GetCursor();
                pDoc->buffer.SetCursor(endP.line, endP.col + 1);
            }
        } else if (hasLeadingAngle) {
            // Already has '<'. Complete after '<'
            auto curPos = pDoc->buffer.GetCursor();
            const auto& curLine = pDoc->buffer.GetLine(curPos.line);
            size_t nextCloseAngle = curLine.find(L'>', curPos.col);
            size_t nextOpenAngle = curLine.find(L'<', curPos.col);
            bool insideExistingTag = (nextCloseAngle != std::wstring::npos && (nextOpenAngle == std::wstring::npos || nextCloseAngle < nextOpenAngle));

            if (insideExistingTag) {
                std::wstring oldLine = curLine;
                for (wchar_t c : item->label) pDoc->buffer.InsertChar(c);
                TryAutoRenameMatchingTag(pDoc, curPos.line, oldLine);
            } else if (isReactComponentTag) {
                std::wstring toInsert = item->label + L" />";
                for (wchar_t c : toInsert) pDoc->buffer.InsertChar(c);
                auto cPos = pDoc->buffer.GetCursor();
                if (cPos.col >= 2) pDoc->buffer.SetCursor(cPos.line, cPos.col - 2);
            } else if (isVoid) {
                std::wstring toInsert;
                if (tagLower == L"img") {
                    toInsert = L"img src=\"\" alt=\"\" />";
                } else if (tagLower == L"input") {
                    toInsert = L"input type=\"text\" />";
                } else if (tagLower == L"link") {
                    toInsert = L"link rel=\"stylesheet\" href=\"\" />";
                } else if (tagLower == L"meta") {
                    toInsert = L"meta charset=\"UTF-8\" />";
                } else {
                    toInsert = item->label + L" />";
                }
                for (wchar_t c : toInsert) pDoc->buffer.InsertChar(c);
            } else {
                // Container tag: e.g. <div -> <div></div> with cursor inside
                std::wstring openPart = item->label + L">";
                std::wstring closePart = L"</" + item->label + L">";
                for (wchar_t c : openPart) pDoc->buffer.InsertChar(c);
                size_t insideLine = pDoc->buffer.GetCursor().line;
                size_t insideCol = pDoc->buffer.GetCursor().col;
                for (wchar_t c : closePart) pDoc->buffer.InsertChar(c);
                pDoc->buffer.SetCursor(insideLine, insideCol);
            }
        } else {
            // No leading '<' (e.g. user typed "div" and picked tag item)
            if (isVoid) {
                std::wstring toInsert;
                if (tagLower == L"img") {
                    toInsert = L"<img src=\"\" alt=\"\" />";
                } else if (tagLower == L"input") {
                    toInsert = L"<input type=\"text\" />";
                } else {
                    toInsert = L"<" + item->label + L" />";
                }
                for (wchar_t c : toInsert) pDoc->buffer.InsertChar(c);
            } else {
                std::wstring openPart = L"<" + item->label + L">";
                std::wstring closePart = L"</" + item->label + L">";
                for (wchar_t c : openPart) pDoc->buffer.InsertChar(c);
                size_t insideLine = pDoc->buffer.GetCursor().line;
                size_t insideCol = pDoc->buffer.GetCursor().col;
                for (wchar_t c : closePart) pDoc->buffer.InsertChar(c);
                pDoc->buffer.SetCursor(insideLine, insideCol);
            }
        }
    } else {
        // Normal completion (method, property, keyword, JSX attribute, etc.)
        for (size_t i = 0; i < prefix.length(); ++i) {
            pDoc->buffer.Backspace();
        }
        std::wstring toInsert = !item->insertText.empty() ? item->insertText : item->label;
        // Avoid duplicating leading '$' or 'ClassName::' if already present right before prefix
        auto curBefore = pDoc->buffer.GetCursor();
        const auto& curLineText = pDoc->buffer.GetLine(curBefore.line);
        if (!toInsert.empty() && toInsert[0] == L'$' && curBefore.col > 0 && curLineText[curBefore.col - 1] == L'$') {
            toInsert = toInsert.substr(1);
        } else {
            size_t dColon = toInsert.find(L"::");
            if (dColon != std::wstring::npos) {
                std::wstring classPrefix = toInsert.substr(0, dColon + 2);
                if (curBefore.col >= classPrefix.length() &&
                    _wcsnicmp(curLineText.c_str() + curBefore.col - classPrefix.length(), classPrefix.c_str(), classPrefix.length()) == 0) {
                    toInsert = toInsert.substr(dColon + 2);
                }
            }
        }

        // Handle CSS property completion (e.g. `width: ;` -> `width: $0;`) so cursor sits before `;`
        if (toInsert.ends_with(L": ;") && toInsert.find(L"$0") == std::wstring::npos) {
            size_t lookCol = curBefore.col;
            while (lookCol < curLineText.length() && (curLineText[lookCol] == L' ' || curLineText[lookCol] == L'\t')) {
                lookCol++;
            }
            if (lookCol < curLineText.length() && curLineText[lookCol] == L':') {
                // Line already has `: ...` after the property name; only insert the property name itself
                toInsert = toInsert.substr(0, toInsert.length() - 3);
            } else if (lookCol < curLineText.length() && curLineText[lookCol] == L';') {
                // Line already has `;` after cursor; don't duplicate `;`
                toInsert = toInsert.substr(0, toInsert.length() - 1) + L"$0";
            } else {
                toInsert = toInsert.substr(0, toInsert.length() - 1) + L"$0;";
            }
        }

        // Expand rich snippet placeholders (${1:...}, ${TM_FILENAME_BASE}, $1, multi-line templates) cleanly via SnippetManager
        const bool hasSnippetSyntax = (toInsert.find(L"${") != std::wstring::npos ||
                                       toInsert.find(L"$1") != std::wstring::npos ||
                                       toInsert.find(L"$2") != std::wstring::npos ||
                                       toInsert.find(L"$TM_") != std::wstring::npos ||
                                       toInsert.find(L'\n') != std::wstring::npos);
        if (hasSnippetSyntax) {
            editor::Snippet inlineSnip;
            inlineSnip.name = item->label;
            inlineSnip.prefix = item->label;
            std::wstringstream ss(toInsert);
            std::wstring sLine;
            while (std::getline(ss, sLine)) {
                if (!sLine.empty() && sLine.back() == L'\r') sLine.pop_back();
                inlineSnip.body.push_back(sLine);
            }
            if (inlineSnip.body.empty()) inlineSnip.body.push_back(toInsert);
            std::wstring fn = pDoc->fileName.empty() ? pDoc->filePath : pDoc->fileName;
            m_snippetManager.ExpandSnippet(inlineSnip, pDoc->buffer, 0, fn);
        } else {
            // Handle `$0` cursor placeholder in single-line insertText (e.g. `className="$0"`, `onClick={$0}`, `width: $0;`)
            size_t dollarZero = toInsert.find(L"$0");
            if (dollarZero != std::wstring::npos) {
                toInsert.erase(dollarZero, 2);
            }
            for (wchar_t c : toInsert) {
                pDoc->buffer.InsertChar(c);
            }
            if (dollarZero != std::wstring::npos) {
                size_t charsAfterCursor = toInsert.length() - dollarZero;
                auto afterPos = pDoc->buffer.GetCursor();
                if (afterPos.col >= charsAfterCursor) {
                    pDoc->buffer.SetCursor(afterPos.line, afterPos.col - charsAfterCursor);
                }
            }
        }
    }

    // Auto-import and "use client" support:
    if (item->documentation.rfind(L"auto-import-stmt:", 0) == 0) {
        editor::ImportCandidate ic;
        ic.symbol = item->label;
        ic.importStatement = item->documentation.substr(17);
        if (!ic.importStatement.empty()) {
            std::wstring targetPath = pDoc->filePath.empty() ? pDoc->fileName : pDoc->filePath;
            std::wstring curText = pDoc->buffer.GetText();
            size_t insLine = 0;
            size_t oldLineCount = pDoc->buffer.GetLineCount();
            auto curPosBefore = pDoc->buffer.GetCursor();
            std::wstring nextText = editor::ImportOrganizer::InsertImportStatement(targetPath, curText, ic, &insLine);
            if (nextText != curText) {
                pDoc->buffer.PushUndo();
                pDoc->buffer.SetText(nextText);
                size_t newLineCount = pDoc->buffer.GetLineCount();
                size_t deltaLines = (newLineCount > oldLineCount) ? (newLineCount - oldLineCount) : 0;
                size_t targetL = curPosBefore.line + ((deltaLines > 0 && insLine <= curPosBefore.line) ? deltaLines : 0);
                targetL = (std::min)(targetL, (newLineCount > 0 ? newLineCount - 1 : 0));
                size_t targetC = (std::min)(curPosBefore.col, pDoc->buffer.GetLine(targetL).size());
                pDoc->buffer.SetCursor(targetL, targetC);
            }
        }
    } else if (item->documentation.rfind(L"auto-import:", 0) == 0) {
        std::wstring modSpec = item->documentation.substr(12);
        EnsureAutoImportAndUseClient(pDoc, item->label, modSpec);
    }

    CancelPendingLspCompletions();
    MarkDocumentModified(pDoc);
    m_editor.DismissAutocomplete();
    m_editor.ClearGhostText();
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

namespace {
static bool s_editDebouncePending = false;
static ULONGLONG s_editDebounceTargetTime = 0;
static std::unordered_set<std::wstring> s_pendingModifiedKeys;
} // namespace

void Window::MarkDocumentModified(editor::OpenDocument* pDoc) {
    if (!pDoc || pDoc->isSpecialView || pDoc->buffer.IsMemoryMappedReadOnly()) return;
    pDoc->isPreview = false;
    pDoc->isDirty = true; // Always mark dirty so changes are never lost
    pDoc->hasExternalDiskConflict = false; // User actively edited; allow auto-save to commit latest changes
    m_lastUserInputTick = GetTickCount64();
    RefreshMergeConflicts(*pDoc);
    SyncDocumentBuffers(pDoc);

    std::wstring key = !pDoc->filePath.empty() ? pDoc->filePath : pDoc->fileName;
    if (!key.empty()) {
        s_pendingModifiedKeys.insert(key);
        s_editDebouncePending = true;
        int delay = ShouldAutoSaveAfterDelay() ? ((m_config.autoSaveDelay > 0) ? m_config.autoSaveDelay : 600) : 300;
        s_editDebounceTargetTime = GetTickCount64() + delay;
    }
}

static std::wstring GetDocumentLowerExtension(const editor::OpenDocument* pDoc);

struct AsyncFormatOnSaveResult {
    std::wstring targetPath;
    std::wstring rawSnapshot;
    std::wstring formattedText;
};

void Window::ApplySaveHooks(editor::OpenDocument& doc, const std::wstring& targetPath, bool allowFormatter) {
    if (doc.isSpecialView || doc.isDiffView || doc.buffer.IsMemoryMappedReadOnly() || targetPath.empty()) return;
    workspace::EditorConfigRules ecRules{};
    if (m_config.enableEditorConfig) {
        ecRules = workspace::WorkspaceConfigEngine::ResolveEditorConfigForFile(targetPath);
        workspace::WorkspaceConfigEngine::ApplyEditorConfigToBufferForSave(doc.buffer, ecRules);
    }
    if (!ecRules.hasTrimTrailingWhitespace && m_config.trimTrailingWhitespace && doc.buffer.GetLineCount() > 0) {
        if (doc.buffer.TrimTrailingWhitespace(0, doc.buffer.GetLineCount() - 1)) {
            auto cur = doc.buffer.GetCursor();
            size_t lineLen = doc.buffer.GetLine(cur.line).length();
            if (cur.col > lineLen) {
                doc.buffer.SetCursor(cur.line, lineLen);
            }
        }
    }
    if (!ecRules.hasInsertFinalNewline && m_config.insertFinalNewline && !doc.buffer.HasTrailingNewline()) {
        doc.buffer.SetHasTrailingNewline(true);
    }

    // Run formatting asynchronously on a background thread so Ctrl+S NEVER freezes the UI.
    // Prettier-handled extensions only format on save when the dedicated `prettierOnSave` setting is enabled (off by default).
    if (allowFormatter) {
        std::wstring ext = std::filesystem::path(targetPath).extension().wstring();
        for (auto& c : ext) c = static_cast<wchar_t>(towlower(c));
        const bool isPrettierExt = editor::FormatEngine::IsPrettierExtension(ext);
        const bool shouldFormat = isPrettierExt ? m_config.prettierOnSave : m_config.formatOnSave;
        if (shouldFormat && editor::FormatEngine::CanFormat(ext)) {
            int tabSize = (m_config.tabSize > 0) ? m_config.tabSize : 4;
            bool insertSpaces = m_config.insertSpaces;
            bool allowPrettier = m_config.prettierOnSave;
            std::wstring rawSnapshot = doc.buffer.GetText();
            HWND postHwnd = GetMainPostHwnd();
            if (!rawSnapshot.empty() && postHwnd) {
                std::thread([this, postHwnd, targetPath, ext, tabSize, insertSpaces, allowPrettier, rawSnapshot = std::move(rawSnapshot)]() mutable {
                    if (m_isDestroying.load()) return;
                    std::wstring formatted = editor::FormatEngine::FormatDocument(
                        rawSnapshot, ext, tabSize, targetPath, insertSpaces, allowPrettier);
                    if (m_isDestroying.load() || formatted.empty() || formatted == rawSnapshot) return;
                    auto* res = new AsyncFormatOnSaveResult{ targetPath, std::move(rawSnapshot), std::move(formatted) };
                    if (!PostMessageW(postHwnd, WM_USER + 239, 0, reinterpret_cast<LPARAM>(res))) {
                        delete res;
                    }
                }).detach();
            }
        }
    }
}

void Window::FlushPendingAutoSaves() {
    if (!m_autoSave || m_config.autoSave == L"off") return;
    bool anySaved = false;
    bool anyStillDirty = false;
    auto flushGroups = [&](std::vector<editor::EditorGroup>& groups) {
        for (auto& group : groups) {
            for (auto& doc : group.docs) {
                if (doc.isDirty && !doc.filePath.empty()) {
                    if (doc.isSpecialView && doc.viewType == L"notebook" && doc.notebookDoc) {
                        doc.notebookDoc->SaveToFile(doc.filePath);
                        doc.isDirty = false;
                        anySaved = true;
                    } else if (!doc.isSpecialView && !doc.hasExternalDiskConflict && !doc.buffer.IsMemoryMappedReadOnly()) {
                        ApplySaveHooks(doc, doc.filePath, false);
                        s_lastInternalAutoSaveTick = GetTickCount64();
                        if (doc.buffer.SaveToFile(doc.filePath)) {
                            s_lastInternalAutoSaveTick = GetTickCount64();
                            doc.isDirty = false;
                            OnDocumentDiskSaved(doc);
                            anySaved = true;
                            SyncRemoteDocumentIfNeeded(doc);
                            ClearStaleExternalLinterProblemsForFile(doc.filePath);
                            ScheduleLangIntelAndLintersAsync(&doc, m_config.enableExternalLinters, true);
                        } else {
                            anyStillDirty = true;
                        }
                    }
                    SyncDocumentBuffers(&doc);
                    if (doc.filePath == m_snippetManager.GetSnippetsFilePath()) {
                        m_snippetManager.LoadSnippets();
                    }
                }
            }
        }
    };
    flushGroups(m_editorGroups);
    for (auto& fw : m_floatingWindows) {
        if (fw && fw->kind == FloatingDockKind::EditorGroup) {
            flushGroups(fw->editorGroups);
        }
    }
    if (anySaved) {
        if (!anyStillDirty) {
            s_pendingModifiedKeys.clear();
            s_editDebouncePending = false;
        }
        UpdateDrawerDirtyFiles();
        m_drawer.RefreshGitStatusOnly(true);
        if (HWND mainHwnd = GetMainPostHwnd()) InvalidateRect(mainHwnd, nullptr, FALSE);
        InvalidateFloatingWindows();
    }
}

void Window::DoCut() {
    if (IsExplorerKeyboardFocused()) {
        CopyExplorerSelectionToClipboard(true);
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }
    auto* pDoc = GetActiveDoc();
    if (pDoc && !pDoc->isSpecialView) {
        if (pDoc->isDiffView && (pDoc->diffActivePane == 0 || pDoc->isDiffRightReadOnly)) return;
        DoCopy();
        if (pDoc->HasAnyMultiCursor()) {
            pDoc->MultiCursorCut();
        } else if (pDoc->HasSelection()) {
            pDoc->DeleteSelection();
        } else {
            pDoc->buffer.DeleteLine(pDoc->buffer.GetCursor().line);
        }
        m_editor.DismissAutocomplete();
        m_editor.ClearGhostText();
        m_editor.ClearPrediction();
        EnsureCursorVisible();
        MarkDocumentModified(pDoc);
        if (pDoc->isDiffView) ComputeDiffHunks(*pDoc);
        InvalidateRect(m_hwnd, nullptr, FALSE);
    }
}

void Window::DoCopy() {
    if (IsExplorerKeyboardFocused()) {
        CopyExplorerSelectionToClipboard(false);
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }
    auto* pDoc = GetActiveDoc();
    if (pDoc && !pDoc->isSpecialView) {
        std::wstring textToCopy;
        if (pDoc->isMultiFileDiff) {
            textToCopy = pDoc->GetMultiFileDiffSelectedText();
        } else if (pDoc->isDiffView) {
            if (pDoc->HasSelection()) {
                textToCopy = pDoc->GetDiffPaneSelectedText();
            } else {
                const auto& srcBuf = (pDoc->diffActivePane == 0) ? pDoc->diffOriginalBuffer : pDoc->buffer;
                auto cursor = srcBuf.GetCursor();
                if (srcBuf.GetLineCount() > 0 && cursor.line < srcBuf.GetLineCount()) {
                    textToCopy = srcBuf.GetLine(cursor.line) + L"\r\n";
                }
            }
        } else if (pDoc->HasAnyMultiCursor()) {
            textToCopy = pDoc->GetMultiCursorCopyText();
        } else if (pDoc->HasSelection()) {
            textToCopy = pDoc->GetSelectedText();
        } else {
            auto cursor = pDoc->buffer.GetCursor();
            textToCopy = pDoc->buffer.GetLine(cursor.line) + L"\r\n";
        }
        // Normalize bare \n to \r\n for Windows clipboard interoperability
        std::wstring winClip;
        winClip.reserve(textToCopy.size() + 16);
        for (size_t i = 0; i < textToCopy.size(); ++i) {
            if (textToCopy[i] == L'\n' && (i == 0 || textToCopy[i - 1] != L'\r')) {
                winClip += L"\r\n";
            } else {
                winClip += textToCopy[i];
            }
        }
        if (!winClip.empty() && OpenClipboard(m_hwnd)) {
            EmptyClipboard();
            size_t bytes = (winClip.length() + 1) * sizeof(wchar_t);
            HGLOBAL hMem = GlobalAlloc(GMEM_MOVEABLE, bytes);
            if (hMem) {
                void* pMem = GlobalLock(hMem);
                if (pMem) {
                    memcpy(pMem, winClip.c_str(), bytes);
                    GlobalUnlock(hMem);
                    SetClipboardData(CF_UNICODETEXT, hMem);
                }
            }
            CloseClipboard();
        }
    }
}

void Window::DoPaste() {
    const bool hasSystemFileDrop = (IsClipboardFormatAvailable(CF_HDROP) != FALSE);
    if (IsExplorerKeyboardFocused() ||
        (!m_activeFloatingWindow && hasSystemFileDrop && m_drawer.HasOpenFolder() &&
         m_config.isDrawerOpen && m_config.activeRailTab == 0)) {
        std::wstring target = (!m_selectedExplorerPath.empty() && !m_explorerClearedSelection)
            ? m_selectedExplorerPath
            : m_drawer.GetOpenFolderPath();
        std::error_code ec;
        bool isDir = !target.empty() && std::filesystem::is_directory(target, ec);
        PasteClipboardToExplorerTarget(target, isDir);
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }
    auto* pDoc = GetActiveDoc();
    if (pDoc && !pDoc->isSpecialView) {
        if (pDoc->buffer.IsMemoryMappedReadOnly()) return;
        if (pDoc->isDiffView && (pDoc->diffActivePane == 0 || pDoc->isDiffRightReadOnly)) return;
        if (OpenClipboard(m_hwnd)) {
            HANDLE hData = GetClipboardData(CF_UNICODETEXT);
            if (hData) {
                wchar_t* pText = static_cast<wchar_t*>(GlobalLock(hData));
                if (pText) {
                    std::wstring clip(pText);
                    GlobalUnlock(hData);
                    CloseClipboard();
                    const bool singleCursorPaste = !pDoc->HasAnyMultiCursor();
                    size_t pasteStartLine = 0, pasteStartCol = 0;
                    if (singleCursorPaste) {
                        if (pDoc->HasSelection()) {
                            size_t eL = 0, eC = 0;
                            pDoc->GetSelectionRange(pasteStartLine, pasteStartCol, eL, eC);
                        } else {
                            auto cur = pDoc->buffer.GetCursor();
                            pasteStartLine = cur.line;
                            pasteStartCol = cur.col;
                        }
                    }
                    pDoc->MultiCursorPaste(clip);
                    if (singleCursorPaste && m_config.formatOnPaste && !pDoc->isDiffView &&
                        pDoc->buffer.GetLineCount() > 0 && pDoc->buffer.GetLineCount() <= 20000) {
                        auto pasteEnd = pDoc->buffer.GetCursor();
                        std::wstring ext = GetDocumentLowerExtension(pDoc);
                        std::wstring rawText = pDoc->buffer.GetText();
                        int tabSize = GetDocTabSize(pDoc);
                        bool insertSpaces = GetDocInsertSpaces(pDoc);
                        std::wstring formatted = editor::FormatEngine::FormatRange(
                            rawText, pasteStartLine, pasteStartCol, pasteEnd.line, pasteEnd.col,
                            ext, tabSize, pDoc->filePath, insertSpaces);
                        if (!formatted.empty() && formatted != rawText) {
                            pDoc->buffer.PushUndo();
                            pDoc->buffer.SetText(formatted);
                            pDoc->ClearSelection();
                            size_t newLC = pDoc->buffer.GetLineCount();
                            size_t cLine = (std::min)(pasteEnd.line, newLC > 0 ? newLC - 1 : 0);
                            size_t cCol = (std::min)(pasteEnd.col, pDoc->buffer.GetLine(cLine).length());
                            pDoc->buffer.SetCursor(cLine, cCol);
                        }
                    }
                    EnsureCursorVisible();
                    MarkDocumentModified(pDoc);
                    if (pDoc->isDiffView) ComputeDiffHunks(*pDoc);
                    InvalidateRect(m_hwnd, nullptr, FALSE);
                    return;
                }
            }
            CloseClipboard();
        }
    }
}

