void Window::UpdateDatabaseModalRuntimeStatus() {
    if (m_hPmaProcess) {
        DWORD exitCode = 0;
        if (GetExitCodeProcess(m_hPmaProcess, &exitCode) && exitCode != STILL_ACTIVE) {
            CloseHandle(m_hPmaProcess);
            m_hPmaProcess = nullptr;
            m_isPmaRunning = false;
        }
    }
    if (m_hMysqlProcess) {
        DWORD exitCode = 0;
        if (GetExitCodeProcess(m_hMysqlProcess, &exitCode) && exitCode != STILL_ACTIVE) {
            CloseHandle(m_hMysqlProcess);
            m_hMysqlProcess = nullptr;
        }
    }
    bool pmaRunning = (m_hPmaProcess != nullptr && m_isPmaRunning);
    bool nginxRunning = (m_hNginxProcess != nullptr || m_header.GetServerState() == ui::ServerState::Running);
    m_dbSettingsModal.SetRuntimeStatus(pmaRunning, nginxRunning);
    if (m_hMysqlProcess == nullptr) {
        int targetPort = 3306;
        try {
            int parsed = std::stoi(m_dbSettingsModal.GetPort());
            if (parsed > 0 && parsed < 65536) targetPort = parsed;
        } catch (...) {}
        std::wstring wsFolder = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L"";
        m_mysqlPort = phide::db::SqlEngine::ResolveDynamicMysqlPort(targetPort, wsFolder);
    }
    m_dbSettingsModal.SetPort(std::to_wstring(m_mysqlPort));
}

void Window::ApplySavedDatabaseAndServerSettings() {
    m_dbSettingsModal.CommitChanges();
    try {
        int p = std::stoi(m_dbSettingsModal.GetPort());
        if (p > 0 && p < 65536 && p != m_mysqlPort) {
            m_mysqlPort = p;
            std::filesystem::path pmaDir = GetPhideRoot() / L"include" / L"phide" / L"db" / L"phpMyAdmin";
            PersistMysqlPortSafe(m_mysqlPort, pmaDir);
        }
    } catch (...) {}
    m_preferredPhpExe = m_dbSettingsModal.GetSelectedPhpExe();
    const bool liveOn = m_dbSettingsModal.IsLiveReloadEnabled();
    m_liveServer.SetLiveReloadEnabled(liveOn);
    for (auto& s : m_activeLiveServers) {
        if (s.server) s.server->SetLiveReloadEnabled(liveOn);
    }
    SaveSessionState();
}

void Window::RevertDatabaseAndServerSettings() {
    m_dbSettingsModal.RevertChanges();
    m_preferredPhpExe = m_dbSettingsModal.GetSelectedPhpExe();
    const bool liveOn = m_dbSettingsModal.IsLiveReloadEnabled();
    m_liveServer.SetLiveReloadEnabled(liveOn);
    for (auto& s : m_activeLiveServers) {
        if (s.server) s.server->SetLiveReloadEnabled(liveOn);
    }
}

void Window::RequestCloseDatabaseSettings(bool saveImmediately) {
    if (saveImmediately) {
        ApplySavedDatabaseAndServerSettings();
        m_dbSettingsModal.Close();
        return;
    }
    if (m_dbSettingsModal.HasUnsavedChanges()) {
        m_confirmDiscardModal.OpenUnsavedSettings(
            L"Changes Never Saved",
            L"Your Database or Web Server settings changes have not been saved.",
            L"Save your changes before closing, or click Close to revert to previous settings."
        );
        return;
    }
    m_dbSettingsModal.Close();
}

bool Window::HandleUnsavedSettingsPopupResult(bool confirmed, bool cancelBtnClicked) {
    if (confirmed) {
        ApplySavedDatabaseAndServerSettings();
        m_dbSettingsModal.Close();
        return true;
    }
    if (cancelBtnClicked) {
        RevertDatabaseAndServerSettings();
        m_dbSettingsModal.Close();
        return true;
    }
    return true;
}

void Window::DoOpenDatabaseSettings(ui::DatabaseModalTab initialTab) {
    UpdateDatabaseModalRuntimeStatus();

    std::wstring sqlName;
    auto checkDirForSql = [](const std::filesystem::path& dir) -> std::wstring {
        if (dir.empty()) return L"";
        std::error_code ec;
        if (std::filesystem::exists(dir / L"database.sql", ec)) return L"database.sql";
        for (const auto& entry : std::filesystem::directory_iterator(dir, ec)) {
            if (entry.is_regular_file(ec) && entry.path().extension() == L".sql") {
                return entry.path().filename().wstring();
            }
        }
        return L"";
    };

    if (!m_workspace.GetRootPath().empty()) {
        sqlName = checkDirForSql(m_workspace.GetRootPath());
    }
    if (sqlName.empty() && !m_runningProjectRoot.empty()) {
        sqlName = checkDirForSql(m_runningProjectRoot);
    }
    std::wstring activeDocPath;
    if (m_focusedGroupIdx >= 0 && m_focusedGroupIdx < (int)m_editorGroups.size()) {
        auto& grp = m_editorGroups[m_focusedGroupIdx];
        if (grp.activeDocIdx >= 0 && grp.activeDocIdx < (int)grp.docs.size()) {
            activeDocPath = grp.docs[grp.activeDocIdx].filePath;
        }
    }
    if (sqlName.empty() && !activeDocPath.empty()) {
        sqlName = checkDirForSql(std::filesystem::path(activeDocPath).parent_path());
    }
    m_dbSettingsModal.SetSqlFileAvailable(sqlName);

    {
        auto phps = server::LiveServer::DiscoverInstalledPhpVersions(GetPhideRoot());
        std::vector<std::pair<std::wstring, std::wstring>> phpPairs;
        for (const auto& p : phps) {
            phpPairs.push_back({ L"PHP " + p.version + L" (" + std::filesystem::path(p.exePath).parent_path().filename().wstring() + L")", p.exePath });
        }
        m_dbSettingsModal.SetAvailablePhpVersions(phpPairs);
    }

    m_dbSettingsModal.Open(initialTab);
    m_header.CloseServerDatabaseDropdowns();
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::RunManualGarbageCollection(bool aggressive) {
    for (auto& group : m_editorGroups) {
        for (auto& doc : group.docs) {
            doc.buffer.RunGarbageCollection(aggressive);
            doc.diffOriginalBuffer.RunGarbageCollection(aggressive);
            doc.mergeCurrentBuffer.RunGarbageCollection(aggressive);
            doc.mergeIncomingBuffer.RunGarbageCollection(aggressive);
            doc.diagnostics.shrink_to_fit();
            doc.inlayHints.shrink_to_fit();
            doc.breakpoints.shrink_to_fit();
            doc.breakpointConditions.shrink_to_fit();
            doc.gutterTestBadges.shrink_to_fit();
            doc.secondarySelections.shrink_to_fit();
            doc.diffHunks.shrink_to_fit();
            doc.diffHunkActionHits.shrink_to_fit();
            doc.gutterDiffBarHits.shrink_to_fit();
            doc.mergeConflicts.shrink_to_fit();
            doc.mergePaneActionHits.shrink_to_fit();
            doc.cssPeek.lines.shrink_to_fit();
            if (!doc.cssPeek.active) {
                doc.cssPeek.lines.clear();
                doc.cssPeek.lines.shrink_to_fit();
            }
            doc.originalDiskText.shrink_to_fit();
            if (doc.notebookDoc) {
                doc.notebookDoc->RunGarbageCollection();
            }
            for (auto& mf : doc.multiFileDiffs) {
                mf.originalBuffer.RunGarbageCollection(aggressive);
                mf.workingBuffer.RunGarbageCollection(aggressive);
                mf.hunks.shrink_to_fit();
            }
            doc.multiFileDiffs.shrink_to_fit();
        }
        group.docs.shrink_to_fit();
    }
    m_editorGroups.shrink_to_fit();
    m_cachedLspCompletions.items.shrink_to_fit();
    m_cachedFilteredProblems.shrink_to_fit();
    m_problemsRowBounds.shrink_to_fit();
    if (aggressive) {
        ClearWindowStaticCaches();
    }
    m_editor.RunGarbageCollection(aggressive);
    if (aggressive) {
        m_drawer.ClearSearchResults();
    }
    m_drawer.RunGarbageCollection();
    m_terminal.RunGarbageCollection();
    m_extensionsPanel.RunGarbageCollection();
    if (aggressive) {
        CoFreeUnusedLibraries();
        _heapmin();
        EmptyWorkingSet(GetCurrentProcess());
        SetProcessWorkingSetSize(GetCurrentProcess(), static_cast<SIZE_T>(-1), static_cast<SIZE_T>(-1));
    }
}

