static void OpenInlineFindOrReplace(editor::OpenDocument* pDoc, ui::EditorCanvas& editor, HWND hwnd,
                                    bool withReplace, const std::function<void()>& fallbackGlobal) {
    if (!pDoc || pDoc->isSpecialView || pDoc->isImageView || pDoc->isUnsupportedBinary) {
        fallbackGlobal();
        return;
    }
    std::wstring seedQuery;
    editor::SearchRangeFilter selRange{};
    bool hasMultiLineSel = false;
    if (pDoc->HasSelection()) {
        auto s = pDoc->selAnchor;
        auto e = pDoc->selEnd;
        if (s.line > e.line || (s.line == e.line && s.col > e.col)) {
            std::swap(s, e);
        }
        if (s.line == e.line) {
            const auto& lineStr = pDoc->buffer.GetLine(s.line);
            if (s.col < lineStr.length()) {
                seedQuery = lineStr.substr(s.col, (std::min)(e.col, lineStr.length()) - s.col);
            }
        } else {
            hasMultiLineSel = true;
            selRange.restrictToRange = true;
            selRange.startLine = s.line;
            selRange.startCol = s.col;
            selRange.endLine = e.line;
            selRange.endCol = e.col;
        }
    } else {
        auto cur = pDoc->buffer.GetCursor();
        if (cur.line < pDoc->buffer.GetLineCount()) {
            const auto& ln = pDoc->buffer.GetLine(cur.line);
            auto isWord = [](wchar_t c) { return iswalnum(c) || c == L'_'; };
            if (!ln.empty()) {
                size_t probe = (cur.col < ln.length()) ? cur.col : (ln.length() - 1);
                if (!isWord(ln[probe]) && probe > 0 && isWord(ln[probe - 1])) probe--;
                if (isWord(ln[probe])) {
                    size_t st = probe;
                    while (st > 0 && isWord(ln[st - 1])) st--;
                    size_t en = probe + 1;
                    while (en < ln.length() && isWord(ln[en])) en++;
                    seedQuery = ln.substr(st, en - st);
                }
            }
        }
    }
    editor.OpenInlineFindBar(withReplace, seedQuery, hasMultiLineSel ? &selRange : nullptr);
    editor.RecomputeInlineFindMatches(*pDoc);
    InvalidateRect(hwnd, nullptr, FALSE);
}

void Window::DoFind() {
    m_editorOverlayOwnerHwnd = m_hwnd.load();
    OpenInlineFindOrReplace(GetActiveDoc(), m_editor, m_hwnd, false, [this]() { DoShowSearch(); });
}

void Window::DoReplace() {
    m_editorOverlayOwnerHwnd = m_hwnd.load();
    OpenInlineFindOrReplace(GetActiveDoc(), m_editor, m_hwnd, true, [this]() { DoShowReplace(); });
}

static std::wstring GetDocumentLowerExtension(const editor::OpenDocument* pDoc) {
    if (!pDoc) return L"";
    std::wstring ext;
    if (!pDoc->filePath.empty()) {
        ext = std::filesystem::path(pDoc->filePath).extension().wstring();
    } else if (!pDoc->fileName.empty()) {
        ext = std::filesystem::path(pDoc->fileName).extension().wstring();
    }
    for (auto& c : ext) c = static_cast<wchar_t>(towlower(c));
    return ext;
}

void Window::DoToggleLineComment() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView) return;
    if (pDoc->isDiffView && (pDoc->diffActivePane == 0 || pDoc->isDiffRightReadOnly)) return;

    std::wstring ext = GetDocumentLowerExtension(pDoc);
    if (!pDoc->HasSelection() && !pDoc->HasAnyMultiCursor()) {
        auto cur = pDoc->buffer.GetCursor();
        std::vector<int> deltas;
        if (pDoc->buffer.ToggleLineCommentRange(cur.line, cur.line, ext, &deltas)) {
            if (!deltas.empty()) {
                int newCol = static_cast<int>(cur.col) + deltas[0];
                pDoc->buffer.SetCursor(cur.line, static_cast<size_t>((std::max)(0, newCol)));
            }
            MarkDocumentModified(pDoc);
            if (pDoc->isDiffView) ComputeDiffHunks(*pDoc);
            InvalidateRect(m_hwnd, nullptr, FALSE);
        }
        return;
    }

    std::vector<std::pair<size_t, size_t>> intervals;
    if (pDoc->isColumnSelection) {
        size_t topL = (std::min)(pDoc->boxAnchorLine, pDoc->boxActiveLine);
        size_t botL = (std::max)(pDoc->boxAnchorLine, pDoc->boxActiveLine);
        intervals.push_back({ topL, botL });
    } else {
        auto addSelInterval = [&](size_t sL, size_t eL, size_t eC) {
            if (eL > sL && eC == 0) --eL;
            intervals.push_back({ sL, eL });
        };
        if (pDoc->HasSelection()) {
            size_t sL, sC, eL, eC;
            pDoc->GetSelectionRange(sL, sC, eL, eC);
            addSelInterval(sL, eL, eC);
        } else {
            auto c = pDoc->buffer.GetCursor();
            addSelInterval(c.line, c.line, c.col);
        }
        for (const auto& sec : pDoc->secondarySelections) {
            size_t sL, sC, eL, eC;
            sec.GetRange(sL, sC, eL, eC);
            addSelInterval(sL, eL, eC);
        }
    }
    if (intervals.empty()) return;
    std::sort(intervals.begin(), intervals.end());
    std::vector<std::pair<size_t, size_t>> merged;
    for (const auto& iv : intervals) {
        if (merged.empty() || iv.first > merged.back().second + 1) {
            merged.push_back(iv);
        } else {
            merged.back().second = (std::max)(merged.back().second, iv.second);
        }
    }

    bool anyChanged = false;
    pDoc->buffer.PushUndo();
    for (const auto& iv : merged) {
        std::vector<int> deltas;
        if (pDoc->buffer.ToggleLineCommentRange(iv.first, iv.second, ext, &deltas)) {
            anyChanged = true;
            auto applyLineDelta = [&](editor::CursorPosition& pos) {
                if (pos.line >= iv.first && pos.line <= iv.second) {
                    size_t idx = pos.line - iv.first;
                    if (idx < deltas.size()) {
                        int nc = static_cast<int>(pos.col) + deltas[idx];
                        pos.col = static_cast<size_t>((std::max)(0, nc));
                    }
                }
            };
            auto c = pDoc->buffer.GetCursor();
            applyLineDelta(c);
            pDoc->buffer.SetCursor(c.line, c.col);
            applyLineDelta(pDoc->selAnchor);
            applyLineDelta(pDoc->selEnd);
            for (auto& sec : pDoc->secondarySelections) {
                applyLineDelta(sec.anchor);
                applyLineDelta(sec.cursor);
            }
        }
    }
    if (anyChanged) {
        MarkDocumentModified(pDoc);
        if (pDoc->isDiffView) ComputeDiffHunks(*pDoc);
        InvalidateRect(m_hwnd, nullptr, FALSE);
    }
}

void Window::DoToggleBlockComment() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView) return;
    if (pDoc->isDiffView && (pDoc->diffActivePane == 0 || pDoc->isDiffRightReadOnly)) return;

    std::wstring ext = GetDocumentLowerExtension(pDoc);
    size_t sL = 0, sC = 0, eL = 0, eC = 0;
    bool hasSel = pDoc->HasSelection();
    if (hasSel) {
        pDoc->GetSelectionRange(sL, sC, eL, eC);
    } else {
        auto c = pDoc->buffer.GetCursor();
        sL = eL = c.line;
        sC = eC = c.col;
    }
    editor::CursorPosition newAnchor, newCursor;
    if (pDoc->buffer.ToggleBlockCommentRange(sL, sC, eL, eC, hasSel, ext, newAnchor, newCursor)) {
        if (hasSel) {
            pDoc->selAnchor = newAnchor;
            pDoc->selEnd = newCursor;
            pDoc->hasSelection = (newAnchor.line != newCursor.line || newAnchor.col != newCursor.col);
        }
        MarkDocumentModified(pDoc);
        if (pDoc->isDiffView) ComputeDiffHunks(*pDoc);
        InvalidateRect(m_hwnd, nullptr, FALSE);
    }
}

void Window::DoEmmetExpand() {
    auto* pDoc = GetActiveDoc();
    if (pDoc && !pDoc->isSpecialView) {
        std::wstring ext;
        if (!pDoc->filePath.empty()) {
            std::filesystem::path p(pDoc->filePath);
            ext = p.extension().wstring();
        } else if (!pDoc->fileName.empty()) {
            std::filesystem::path p(pDoc->fileName);
            ext = p.extension().wstring();
        }
        if (!ext.empty() && ext[0] == L'.') ext = ext.substr(1);
        if (pDoc->buffer.ExpandEmmet(ext)) {
            MarkDocumentModified(pDoc);
            InvalidateRect(m_hwnd, nullptr, FALSE);
        }
    }
}

void Window::DoEmmetWrapWithAbbreviation() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView || pDoc->buffer.IsMemoryMappedReadOnly()) return;
    if (pDoc->isDiffView && (pDoc->diffActivePane == 0 || pDoc->isDiffRightReadOnly)) return;
    m_bpPromptMode = InlinePromptMode::EmmetWrap;
    m_bpPromptInput = L"div";
    m_bpPromptOpen = true;
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoEmmetBalance(bool outward) {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView || pDoc->buffer.IsMemoryMappedReadOnly()) return;
    if (pDoc->BalanceEmmetTag(outward)) {
        EnsureCursorVisible();
        InvalidateRect(m_hwnd, nullptr, FALSE);
    }
}

void Window::DoTransformCase(editor::CaseTransform mode) {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView || pDoc->buffer.IsMemoryMappedReadOnly()) return;
    if (pDoc->isDiffView && (pDoc->diffActivePane == 0 || pDoc->isDiffRightReadOnly)) return;
    if (pDoc->TransformSelectionCase(mode)) {
        EnsureCursorVisible();
        MarkDocumentModified(pDoc);
        if (pDoc->isDiffView) ComputeDiffHunks(*pDoc);
        InvalidateRect(m_hwnd, nullptr, FALSE);
    }
}

