static std::string WideToUtf8Simple(const std::wstring& w) {
    if (w.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, w.c_str(), static_cast<int>(w.length()), nullptr, 0, nullptr, nullptr);
    if (len <= 0) return "";
    std::string out(len, '\0');
    WideCharToMultiByte(CP_UTF8, 0, w.c_str(), static_cast<int>(w.length()), out.data(), len, nullptr, nullptr);
    return out;
}

static std::wstring Utf8ToWideSimple(const std::string& u) {
    if (u.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, u.c_str(), static_cast<int>(u.length()), nullptr, 0);
    if (len <= 0) return L"";
    std::wstring out(len, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, u.c_str(), static_cast<int>(u.length()), out.data(), len);
    return out;
}

static std::string EscapeJsonStringUtf8(const std::string& s) {
    std::string out;
    out.reserve(s.size() + 8);
    for (char ch : s) {
        if (ch == '\\') out += "\\\\";
        else if (ch == '"') out += "\\\"";
        else if (ch == '\n') out += "\\n";
        else if (ch == '\r') out += "\\r";
        else if (ch == '\t') out += "\\t";
        else out += ch;
    }
    return out;
}

void Window::SaveBookmarksForWorkspace() {
    for (const auto& grp : m_editorGroups) {
        for (const auto& doc : grp.docs) {
            if (doc.filePath.empty() || doc.isSpecialView) continue;
            std::wstring key = NormalizeBookmarkKey(doc.filePath);
            if (doc.bookmarks.empty()) {
                m_persistedBookmarks.erase(key);
            } else {
                m_persistedBookmarks[key] = doc.bookmarks;
            }
        }
    }
    if (!m_drawer.HasOpenFolder() || m_drawer.GetOpenFolderPath().empty()) return;
    std::filesystem::path bmPath = std::filesystem::path(m_drawer.GetOpenFolderPath()) / L".phide" / L"bookmarks.json";
    std::error_code ec;
    if (m_persistedBookmarks.empty()) {
        if (std::filesystem::exists(bmPath, ec)) {
            std::filesystem::remove(bmPath, ec);
        }
        return;
    }
    workspace::IgnoreEngine::EnsurePhideIgnoredForPath(bmPath);
    std::filesystem::create_directories(bmPath.parent_path(), ec);
    std::ofstream out(bmPath, std::ios::binary | std::ios::trunc);
    if (!out.is_open()) return;
    out << "{\n";
    size_t idx = 0;
    for (const auto& [k, lines] : m_persistedBookmarks) {
        out << "  \"" << EscapeJsonStringUtf8(WideToUtf8Simple(k)) << "\": [";
        for (size_t j = 0; j < lines.size(); ++j) {
            out << lines[j];
            if (j + 1 < lines.size()) out << ", ";
        }
        out << "]";
        if (++idx < m_persistedBookmarks.size()) out << ",";
        out << "\n";
    }
    out << "}\n";
}

void Window::LoadBookmarksForWorkspace() {
    m_persistedBookmarks.clear();
    if (!m_drawer.HasOpenFolder() || m_drawer.GetOpenFolderPath().empty()) return;
    std::filesystem::path bmPath = std::filesystem::path(m_drawer.GetOpenFolderPath()) / L".phide" / L"bookmarks.json";
    std::error_code ec;
    if (!std::filesystem::exists(bmPath, ec)) return;
    std::ifstream in(bmPath, std::ios::binary);
    if (!in.is_open()) return;
    std::string line;
    while (std::getline(in, line)) {
        size_t q1 = line.find('"');
        if (q1 == std::string::npos) continue;
        std::string rawKey;
        size_t p = q1 + 1;
        while (p < line.size()) {
            if (line[p] == '\\' && p + 1 < line.size()) {
                rawKey += line[p + 1];
                p += 2;
            } else if (line[p] == '"') {
                break;
            } else {
                rawKey += line[p];
                p++;
            }
        }
        size_t lb = line.find('[', p);
        size_t rb = line.find(']', p);
        if (lb == std::string::npos || rb == std::string::npos || rb <= lb) continue;
        std::vector<size_t> lines;
        std::string nums = line.substr(lb + 1, rb - lb - 1);
        std::stringstream ss(nums);
        std::string tok;
        while (std::getline(ss, tok, ',')) {
            try {
                size_t val = static_cast<size_t>(std::stoull(tok));
                lines.push_back(val);
            } catch (...) {}
        }
        if (!rawKey.empty() && !lines.empty()) {
            m_persistedBookmarks[NormalizeBookmarkKey(Utf8ToWideSimple(rawKey))] = std::move(lines);
        }
    }
    for (auto& grp : m_editorGroups) {
        for (auto& doc : grp.docs) {
            if (doc.filePath.empty() || doc.isSpecialView) continue;
            auto it = m_persistedBookmarks.find(NormalizeBookmarkKey(doc.filePath));
            if (it != m_persistedBookmarks.end()) {
                doc.bookmarks.clear();
                size_t lineCnt = doc.buffer.GetLineCount();
                for (size_t bl : it->second) {
                    if (bl < lineCnt) doc.bookmarks.push_back(bl);
                }
            }
        }
    }
}

namespace {
void ApplySingleMatchReplacement(editor::Buffer& buffer, size_t lineIdx, size_t col, size_t len, const std::wstring& rep) {
    if (lineIdx >= buffer.GetLineCount()) return;
    const std::wstring lineStr = buffer.GetLine(lineIdx);
    if (col + len > lineStr.length()) return;
    const std::wstring prefix = lineStr.substr(0, col);
    const std::wstring suffix = lineStr.substr(col + len);
    if (rep.find(L'\n') == std::wstring::npos && rep.find(L'\r') == std::wstring::npos) {
        buffer.SetLine(lineIdx, prefix + rep + suffix);
        return;
    }
    std::vector<std::wstring> sliceLines;
    std::wstring clean;
    clean.reserve(rep.size());
    for (wchar_t c : rep) {
        if (c != L'\r') clean.push_back(c);
    }
    size_t pos = 0;
    while (true) {
        size_t nl = clean.find(L'\n', pos);
        if (nl == std::wstring::npos) {
            sliceLines.push_back(clean.substr(pos));
            break;
        }
        sliceLines.push_back(clean.substr(pos, nl - pos));
        pos = nl + 1;
    }
    if (sliceLines.empty()) sliceLines.push_back(L"");
    sliceLines.front() = prefix + sliceLines.front();
    sliceLines.back() += suffix;
    buffer.ReplaceLineSlice(lineIdx, 1, sliceLines);
}
} // namespace

void Window::ApplyInlineFindReplaceCurrent() {
    auto* pDoc = GetActiveDoc();
    auto& fb = m_editor.GetFindBar();
    if (!pDoc || pDoc->isSpecialView || !fb.isOpen || fb.query.empty()) return;
    if (pDoc->buffer.IsMemoryMappedReadOnly()) return;
    if (fb.matches.empty()) m_editor.RecomputeInlineFindMatches(*pDoc);
    if (fb.matches.empty()) return;
    if (fb.currentMatchIdx < 0 || fb.currentMatchIdx >= static_cast<int>(fb.matches.size())) {
        fb.currentMatchIdx = 0;
    }
    const auto m = fb.matches[fb.currentMatchIdx];
    if (m.line >= pDoc->buffer.GetLineCount()) return;
    std::wstring lineStr = pDoc->buffer.GetLine(m.line);
    if (m.col + m.length > lineStr.length()) return;
    std::wstring rep = editor::ExpandSpecificMatchReplacement(
        lineStr, m.col, m.length, fb.query, fb.replaceQuery,
        fb.matchCase, fb.wholeWord, fb.useRegex, fb.preserveCase);
    pDoc->buffer.PushUndo();
    ApplySingleMatchReplacement(pDoc->buffer, m.line, m.col, m.length, rep);
    MarkDocumentModified(pDoc);
    m_editor.RecomputeInlineFindMatches(*pDoc);
    if (!fb.matches.empty()) {
        if (fb.currentMatchIdx >= static_cast<int>(fb.matches.size())) fb.currentMatchIdx = 0;
        const auto& nextM = fb.matches[fb.currentMatchIdx];
        pDoc->buffer.SetCursor(nextM.line, nextM.col + nextM.length);
        pDoc->selAnchor = { nextM.line, nextM.col };
        pDoc->selEnd = { nextM.line, nextM.col + nextM.length };
        pDoc->hasSelection = true;
        EnsureCursorVisible();
    }
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::ApplyInlineFindReplaceAll() {
    auto* pDoc = GetActiveDoc();
    auto& fb = m_editor.GetFindBar();
    if (!pDoc || pDoc->isSpecialView || !fb.isOpen || fb.query.empty()) return;
    if (pDoc->buffer.IsMemoryMappedReadOnly()) return;
    m_editor.RecomputeInlineFindMatches(*pDoc);
    if (fb.matches.empty()) return;

    pDoc->buffer.PushUndo();
    for (int i = static_cast<int>(fb.matches.size()) - 1; i >= 0; --i) {
        const auto& m = fb.matches[i];
        if (m.line >= pDoc->buffer.GetLineCount()) continue;
        std::wstring lineStr = pDoc->buffer.GetLine(m.line);
        if (m.col + m.length > lineStr.length()) continue;
        std::wstring rep = editor::ExpandSpecificMatchReplacement(
            lineStr, m.col, m.length, fb.query, fb.replaceQuery,
            fb.matchCase, fb.wholeWord, fb.useRegex, fb.preserveCase);
        ApplySingleMatchReplacement(pDoc->buffer, m.line, m.col, m.length, rep);
    }
    MarkDocumentModified(pDoc);
    m_editor.RecomputeInlineFindMatches(*pDoc);
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoGoToDefinition() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView) return;

    std::wstring sym = ExtractWordUnderCursor(*pDoc);
    if (sym.empty()) return;
    auto pos = pDoc->buffer.GetCursor();

    if (m_lsp.IsRunning() && !pDoc->filePath.empty()) {
        std::vector<lsp::Location> locs;
        if (m_lsp.RequestDefinitionLocations(pDoc->filePath, pos.line, pos.col, locs) && !locs.empty()) {
            RecordNavCheckpoint();
            if (locs.size() == 1) {
                JumpToFileAndLocation(locs[0].filePath, locs[0].line, locs[0].col);
            } else {
                std::vector<ui::EditorCanvas::PeekItemEntry> entries;
                for (const auto& l : locs) {
                    ui::EditorCanvas::PeekItemEntry e;
                    e.filePath = l.filePath;
                    e.line = l.line;
                    e.col = l.col;
                    e.label = std::filesystem::path(l.filePath).filename().wstring() + L":" + std::to_wstring(l.line + 1);
                    e.detail = sym;
                    entries.push_back(std::move(e));
                }
                m_editor.OpenPeekPanel(ui::EditorCanvas::PeekMode::PeekDefinition,
                                       L"Definitions: " + sym, L"", pos.line, std::move(entries));
                InvalidateRect(m_hwnd, nullptr, FALSE);
            }
            return;
        }
    }

    auto findDefInLines = [&](const std::vector<std::wstring>& lines, const std::wstring& filePath,
                              size_t& outLine, size_t& outCol) -> bool {
        auto isSymChar = [](wchar_t ch) { return iswalnum(ch) || ch == L'_'; };
        static const wchar_t* const prefixes[] = {
            L"function ", L"class ", L"interface ", L"trait ", L"struct ",
            L"enum ", L"def ", L"async def ", L"async function ", L"fn ",
            L"func ", L"const ", L"let ", L"var ", L"type "
        };
        for (size_t li = 0; li < lines.size(); ++li) {
            const auto& ln = lines[li];
            if (ln.find(sym) == std::wstring::npos) continue;
            for (const auto* kw : prefixes) {
                size_t kwLen = wcslen(kw);
                size_t kPos = ln.find(kw);
                if (kPos != std::wstring::npos) {
                    if (kPos > 0 && isSymChar(ln[kPos - 1])) continue;
                    size_t namePos = kPos + kwLen;
                    while (namePos < ln.length() && (ln[namePos] == L' ' || ln[namePos] == L'\t' || ln[namePos] == L'&')) {
                        namePos++;
                    }
                    if (ln.compare(namePos, sym.length(), sym) == 0) {
                        size_t after = namePos + sym.length();
                        bool boundaryOk = (after >= ln.length() || !isSymChar(ln[after]));
                        if (boundaryOk && (_wcsicmp(filePath.c_str(), pDoc->filePath.c_str()) != 0 || li != pos.line)) {
                            outLine = li;
                            outCol = namePos;
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    };

    size_t foundL = 0, foundC = 0;
    if (findDefInLines(pDoc->buffer.GetLines(), pDoc->filePath, foundL, foundC)) {
        RecordNavCheckpoint();
        JumpToFileAndLocation(pDoc->filePath, foundL, foundC);
        return;
    }

    for (const auto& grp : m_editorGroups) {
        for (const auto& d : grp.docs) {
            if (d.isSpecialView || d.filePath.empty()) continue;
            if (findDefInLines(d.buffer.GetLines(), d.filePath, foundL, foundC)) {
                RecordNavCheckpoint();
                JumpToFileAndLocation(d.filePath, foundL, foundC);
                return;
            }
        }
    }

    auto indexed = m_symbolIndex.FindDefinitions(sym, pDoc->filePath);
    for (const auto& cand : indexed) {
        if (_wcsicmp(cand.filePath.c_str(), pDoc->filePath.c_str()) != 0 || cand.line != pos.line) {
            RecordNavCheckpoint();
            JumpToFileAndLocation(cand.filePath, cand.line, cand.col);
            return;
        }
    }

    m_editor.ShowRefactorPopup(L"No definition found for \"" + sym + L"\"");
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoPeekDefinition() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView) return;
    std::wstring sym = ExtractWordUnderCursor(*pDoc);
    if (sym.empty()) return;
    auto pos = pDoc->buffer.GetCursor();

    std::vector<ui::EditorCanvas::PeekItemEntry> items;
    if (m_lsp.IsRunning() && !pDoc->filePath.empty()) {
        std::vector<lsp::Location> locs;
        if (m_lsp.RequestDefinitionLocations(pDoc->filePath, pos.line, pos.col, locs)) {
            for (const auto& l : locs) {
                ui::EditorCanvas::PeekItemEntry e;
                e.filePath = l.filePath;
                e.line = l.line;
                e.col = l.col;
                e.label = std::filesystem::path(l.filePath).filename().wstring() + L":" + std::to_wstring(l.line + 1);
                e.detail = L"LSP Definition";
                items.push_back(std::move(e));
            }
        }
    }
    if (items.empty()) {
        auto indexed = m_symbolIndex.FindDefinitions(sym, pDoc->filePath);
        for (const auto& cand : indexed) {
            ui::EditorCanvas::PeekItemEntry e;
            e.filePath = cand.filePath;
            e.line = cand.line;
            e.col = cand.col;
            e.label = std::filesystem::path(cand.filePath).filename().wstring() + L":" + std::to_wstring(cand.line + 1);
            e.detail = cand.detail.empty() ? sym : cand.detail;
            items.push_back(std::move(e));
        }
    }
    if (items.empty()) {
        std::wstring wsRoot = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L"";
        auto snaps = CollectOpenDocSnapshots(m_editorGroups);
        auto refs = editor::FindWorkspaceReferences(sym, wsRoot, m_drawer.GetIgnoreEngine(), snaps, 500, 80);
        for (const auto& r : refs) {
            ui::EditorCanvas::PeekItemEntry e;
            e.filePath = r.filePath;
            e.line = r.line;
            e.col = r.col;
            e.label = std::filesystem::path(r.filePath).filename().wstring() + L":" + std::to_wstring(r.line + 1);
            e.detail = r.previewLine;
            e.snippet = r.previewLine;
            items.push_back(std::move(e));
        }
    }
    if (items.empty()) {
        m_editor.ShowRefactorPopup(L"No definition found to peek for \"" + sym + L"\"");
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }
    m_editor.OpenPeekPanel(ui::EditorCanvas::PeekMode::PeekDefinition,
                           L"Peek Definition: " + sym,
                           std::to_wstring(items.size()) + L" match(es)",
                           pos.line, std::move(items));
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoTypeDefinition() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView) return;
    std::wstring sym = ExtractWordUnderCursor(*pDoc);
    if (sym.empty()) return;
    auto pos = pDoc->buffer.GetCursor();
    if (m_lsp.IsRunning() && !pDoc->filePath.empty()) {
        std::vector<lsp::Location> locs;
        if (m_lsp.RequestTypeDefinition(pDoc->filePath, pos.line, pos.col, locs) && !locs.empty()) {
            RecordNavCheckpoint();
            JumpToFileAndLocation(locs[0].filePath, locs[0].line, locs[0].col);
            return;
        }
    }
    DoGoToDefinition();
}

void Window::DoImplementation() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView) return;
    std::wstring sym = ExtractWordUnderCursor(*pDoc);
    if (sym.empty()) return;
    auto pos = pDoc->buffer.GetCursor();
    std::vector<ui::EditorCanvas::PeekItemEntry> items;
    if (m_lsp.IsRunning() && !pDoc->filePath.empty()) {
        std::vector<lsp::Location> locs;
        if (m_lsp.RequestImplementation(pDoc->filePath, pos.line, pos.col, locs)) {
            for (const auto& l : locs) {
                ui::EditorCanvas::PeekItemEntry e;
                e.filePath = l.filePath;
                e.line = l.line;
                e.col = l.col;
                e.label = std::filesystem::path(l.filePath).filename().wstring() + L":" + std::to_wstring(l.line + 1);
                e.detail = L"Implementation";
                items.push_back(std::move(e));
            }
        }
    }
    if (items.size() == 1) {
        RecordNavCheckpoint();
        JumpToFileAndLocation(items[0].filePath, items[0].line, items[0].col);
        return;
    }
    if (items.empty()) {
        auto indexed = m_symbolIndex.FindDefinitions(sym, pDoc->filePath);
        for (const auto& cand : indexed) {
            ui::EditorCanvas::PeekItemEntry e;
            e.filePath = cand.filePath;
            e.line = cand.line;
            e.col = cand.col;
            e.label = std::filesystem::path(cand.filePath).filename().wstring() + L":" + std::to_wstring(cand.line + 1);
            e.detail = cand.detail;
            items.push_back(std::move(e));
        }
    }
    if (items.empty()) {
        m_editor.ShowRefactorPopup(L"No implementation found for \"" + sym + L"\"");
    } else if (items.size() == 1) {
        RecordNavCheckpoint();
        JumpToFileAndLocation(items[0].filePath, items[0].line, items[0].col);
    } else {
        m_editor.OpenPeekPanel(ui::EditorCanvas::PeekMode::PeekDefinition,
                               L"Implementations: " + sym,
                               std::to_wstring(items.size()) + L" implementation(s)",
                               pos.line, std::move(items));
    }
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoFindReferences(const std::wstring& symbolOverride, size_t anchorLineOverride) {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView) return;
    std::wstring sym = !symbolOverride.empty() ? symbolOverride : ExtractWordUnderCursor(*pDoc);
    if (sym.empty()) return;
    auto pos = pDoc->buffer.GetCursor();
    size_t anchorLine = (anchorLineOverride != static_cast<size_t>(-1)) ? anchorLineOverride : pos.line;
    size_t reqCol = pos.col;
    if (!symbolOverride.empty() && anchorLine < pDoc->buffer.GetLineCount()) {
        size_t foundCol = pDoc->buffer.GetLine(anchorLine).find(sym);
        if (foundCol != std::wstring::npos) reqCol = foundCol;
    }

    std::vector<ui::EditorCanvas::PeekItemEntry> items;
    if (m_lsp.IsRunning() && !pDoc->filePath.empty()) {
        std::vector<lsp::Location> locs;
        if (m_lsp.RequestReferences(pDoc->filePath, anchorLine, reqCol, true, locs)) {
            for (const auto& l : locs) {
                ui::EditorCanvas::PeekItemEntry e;
                e.filePath = l.filePath;
                e.line = l.line;
                e.col = l.col;
                e.label = std::filesystem::path(l.filePath).filename().wstring() + L":" + std::to_wstring(l.line + 1);
                e.detail = L"LSP Reference";
                items.push_back(std::move(e));
            }
        }
    }
    if (items.empty()) {
        std::wstring wsRoot = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L"";
        auto snaps = CollectOpenDocSnapshots(m_editorGroups);
        auto refs = editor::FindWorkspaceReferences(sym, wsRoot, m_drawer.GetIgnoreEngine(), snaps);
        for (const auto& r : refs) {
            ui::EditorCanvas::PeekItemEntry e;
            e.filePath = r.filePath;
            e.line = r.line;
            e.col = r.col;
            e.label = std::filesystem::path(r.filePath).filename().wstring() + L":" + std::to_wstring(r.line + 1);
            e.detail = r.previewLine;
            e.snippet = r.previewLine;
            items.push_back(std::move(e));
        }
    }
    if (items.empty()) {
        m_editor.ShowRefactorPopup(L"No references found for \"" + sym + L"\"");
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }
    m_editor.OpenPeekPanel(ui::EditorCanvas::PeekMode::References,
                           L"References: " + sym,
                           std::to_wstring(items.size()) + L" reference(s)",
                           anchorLine, std::move(items));
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoCallHierarchy() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView) return;
    std::wstring sym = ExtractWordUnderCursor(*pDoc);
    if (sym.empty()) return;
    auto pos = pDoc->buffer.GetCursor();

    std::vector<ui::EditorCanvas::PeekItemEntry> items;
    if (m_lsp.IsRunning() && !pDoc->filePath.empty()) {
        std::vector<lsp::CallHierarchyItem> roots;
        if (m_lsp.PrepareCallHierarchy(pDoc->filePath, pos.line, pos.col, roots) && !roots.empty()) {
            std::vector<lsp::CallHierarchyItem> incoming, outgoing;
            m_lsp.RequestIncomingCalls(roots[0], incoming);
            m_lsp.RequestOutgoingCalls(roots[0], outgoing);
            for (const auto& c : incoming) {
                ui::EditorCanvas::PeekItemEntry e;
                e.filePath = c.filePath;
                e.line = c.line;
                e.col = c.col;
                e.label = L"[Caller] " + c.name;
                e.detail = std::filesystem::path(c.filePath).filename().wstring() + L":" + std::to_wstring(c.line + 1);
                items.push_back(std::move(e));
            }
            for (const auto& c : outgoing) {
                ui::EditorCanvas::PeekItemEntry e;
                e.filePath = c.filePath;
                e.line = c.line;
                e.col = c.col;
                e.label = L"[Callee] " + c.name;
                e.detail = std::filesystem::path(c.filePath).filename().wstring() + L":" + std::to_wstring(c.line + 1);
                items.push_back(std::move(e));
            }
        }
    }
    if (items.empty()) {
        std::wstring wsRoot = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L"";
        auto snaps = CollectOpenDocSnapshots(m_editorGroups);
        std::wstring activePath = pDoc->filePath.empty() ? pDoc->fileName : pDoc->filePath;
        auto nodes = editor::BuildStaticCallHierarchy(sym, activePath, wsRoot, m_drawer.GetIgnoreEngine(), snaps);
        for (const auto& n : nodes) {
            ui::EditorCanvas::PeekItemEntry e;
            e.filePath = n.filePath;
            e.line = n.line;
            e.col = n.col;
            e.label = (n.isIncoming ? L"[Caller] " : L"[Callee] ") + n.name;
            e.detail = n.detail;
            items.push_back(std::move(e));
        }
    }
    m_editor.OpenPeekPanel(ui::EditorCanvas::PeekMode::CallHierarchy,
                           L"Call Hierarchy: " + sym,
                           std::to_wstring(items.size()) + L" call edge(s)",
                           pos.line, std::move(items));
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoCodeMetrics() {
    std::wstring wsRoot = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L"";
    auto snaps = CollectOpenDocSnapshots(m_editorGroups);

    // Compute only the active open file's summary synchronously (<1 ms);
    // run the workspace-wide directory/AST scan on a background thread so UI stays responsive.
    std::wstring activeSummary = L"No active file";
    size_t anchorLine = 0;
    if (auto* pDoc = GetActiveDoc(); pDoc && !pDoc->isSpecialView && !pDoc->isUnsupportedBinary) {
        std::wstring p = pDoc->filePath.empty() ? pDoc->fileName : pDoc->filePath;
        std::wstring ext = std::filesystem::path(p).extension().wstring();
        for (auto& c : ext) c = static_cast<wchar_t>(towlower(c));
        auto fm = editor::ComputeFileMetrics(p, pDoc->buffer.GetText(), ext);
        activeSummary = std::filesystem::path(p).filename().wstring() +
                        L" — " + std::to_wstring(fm.codeLines) + L" LOC, " +
                        std::to_wstring(fm.functionCount) + L" funcs, " +
                        L"complexity " + std::to_wstring(fm.cyclomaticComplexity);
        anchorLine = pDoc->buffer.GetCursor().line;
    }

    const uint64_t gen = ++m_codeMetricsGen;
    m_editor.OpenCodeMetricsLoadingPanel(activeSummary);
    m_editor.GetPeekPanel().anchorLine = anchorLine;
    if (m_hwnd) {
        SetTimer(m_hwnd, m_animTimerId, 16, nullptr);
        InvalidateRect(m_hwnd, nullptr, FALSE);
    }

    {
        std::lock_guard<std::mutex> lk(m_bgWorkersMutex);
        if (m_isDestroying.load()) return;
        ++m_activeBgWorkers;
    }

    auto ignoreCopy = std::make_shared<workspace::IgnoreEngine>();
    ignoreCopy->CopyFrom(m_drawer.GetIgnoreEngine());
    HWND postHwnd = m_hwnd.load();

    std::thread([this, postHwnd, gen, wsRoot = std::move(wsRoot), ignoreCopy, snaps = std::move(snaps),
                 activeSummary = std::move(activeSummary), anchorLine]() mutable {
        struct Guard {
            Window* self;
            ~Guard() {
                std::lock_guard<std::mutex> lk(self->m_bgWorkersMutex);
                if (self->m_activeBgWorkers > 0) --self->m_activeBgWorkers;
                self->m_bgWorkersCv.notify_all();
            }
        } guard{ this };
        try {
            if (m_isDestroying.load() || m_codeMetricsGen.load() != gen) return;
            auto metrics = editor::ComputeWorkspaceMetrics(wsRoot, *ignoreCopy, snaps);
            if (m_isDestroying.load() || m_codeMetricsGen.load() != gen) return;

            {
                std::lock_guard<std::mutex> lk(m_codeMetricsMutex);
                if (m_codeMetricsGen.load() != gen) return;
                m_pendingCodeMetrics.generation = gen;
                m_pendingCodeMetrics.metrics = std::move(metrics);
                m_pendingCodeMetrics.activeSummary = std::move(activeSummary);
                m_pendingCodeMetrics.anchorLine = anchorLine;
                m_hasPendingCodeMetrics = true;
            }
            if (postHwnd && IsWindow(postHwnd) && !m_isDestroying.load()) {
                PostMessageW(postHwnd, WM_USER + 236, 0, 0);
            }
        } catch (...) {}
    }).detach();
}

void Window::ApplyPendingCodeMetrics() {
    PendingCodeMetricsResult res;
    {
        std::lock_guard<std::mutex> lk(m_codeMetricsMutex);
        if (!m_hasPendingCodeMetrics) return;
        res = std::move(m_pendingCodeMetrics);
        m_pendingCodeMetrics = {};
        m_hasPendingCodeMetrics = false;
    }

    if (res.generation != m_codeMetricsGen.load()) return;
    const auto& peek = m_editor.GetPeekPanel();
    // Respect if the user closed or switched away from the loading peek panel while scanning
    if (!peek.isOpen || peek.mode != ui::EditorCanvas::PeekMode::CodeMetrics) return;

    m_editor.OpenCodeMetricsPanel(res.metrics, res.activeSummary);
    m_editor.GetPeekPanel().anchorLine = res.anchorLine;
    if (m_hwnd) InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::DoRenameSymbol() {
    auto* pDoc = GetActiveDoc();
    if (!pDoc || pDoc->isSpecialView || pDoc->isUnsupportedBinary) return;
    if (pDoc->isDiffView && (pDoc->diffActivePane == 0 || pDoc->isDiffRightReadOnly)) return;

    std::wstring sym = ExtractWordUnderCursor(*pDoc);
    if (sym.empty()) {
        m_editor.ShowRefactorPopup(L"Place cursor on an identifier to rename");
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }
    auto pos = pDoc->buffer.GetCursor();
    std::wstring statusNote = L"Workspace rename";
    if (m_lsp.IsRunning() && !pDoc->filePath.empty()) {
        size_t sCol = 0, eCol = 0;
        std::wstring placeholder;
        if (m_lsp.PrepareRename(pDoc->filePath, pos.line, pos.col, sCol, eCol, placeholder)) {
            if (!placeholder.empty()) sym = placeholder;
            statusNote = L"LSP rename";
        }
    }
    std::wstring wsRoot = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L"";
    auto snaps = CollectOpenDocSnapshots(m_editorGroups);
    auto plan = editor::BuildStaticRenamePlan(sym, sym, wsRoot, m_drawer.GetIgnoreEngine(), snaps);
    m_editor.OpenRenameWidget(sym, std::move(plan), statusNote);
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

void Window::ApplyCrossFileRename(const std::wstring& newName) {
    auto* pDoc = GetActiveDoc();
    const auto& rw = m_editor.GetRenameWidget();
    std::wstring oldName = rw.oldName;
    if (oldName.empty() || newName.empty() || oldName == newName) {
        m_editor.CloseRenameWidget();
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }

    auto normKey = [](std::wstring s) {
        for (auto& c : s) { if (c == L'/') c = L'\\'; c = static_cast<wchar_t>(towlower(c)); }
        return s;
    };

    size_t filesTouched = 0;
    size_t editsApplied = 0;

    if (m_lsp.IsRunning() && pDoc && !pDoc->filePath.empty()) {
        lsp::WorkspaceEditResult wsEdit;
        auto pos = pDoc->buffer.GetCursor();
        if (m_lsp.RequestRename(pDoc->filePath, pos.line, pos.col, newName, wsEdit) && !wsEdit.fileChanges.empty()) {
            for (const auto& [filePath, edits] : wsEdit.fileChanges) {
                std::wstring key = normKey(filePath);
                std::vector<lsp::LspTextEdit> sortedEdits = edits;
                std::sort(sortedEdits.begin(), sortedEdits.end(), [](const lsp::LspTextEdit& a, const lsp::LspTextEdit& b) {
                    if (a.startLine != b.startLine) return a.startLine > b.startLine;
                    return a.startCol > b.startCol;
                });

                bool matchedOpen = false;
                for (auto& grp : m_editorGroups) {
                    for (auto& d : grp.docs) {
                        if (d.isSpecialView || d.filePath.empty()) continue;
                        if (normKey(d.filePath) != key) continue;
                        d.buffer.PushUndo();
                        for (const auto& ed : sortedEdits) {
                            if (ed.startLine < d.buffer.GetLineCount() && ed.startLine == ed.endLine) {
                                std::wstring ln = d.buffer.GetLine(ed.startLine);
                                size_t sc = (std::min)(ed.startCol, ln.length());
                                size_t ec = (std::min)(ed.endCol, ln.length());
                                d.buffer.SetLine(ed.startLine, ln.substr(0, sc) + ed.newText + ln.substr(ec));
                                editsApplied++;
                            }
                        }
                        MarkDocumentModified(&d);
                        matchedOpen = true;
                        filesTouched++;
                    }
                }
                if (!matchedOpen) {
                    editor::Buffer diskBuf;
                    if (diskBuf.LoadFromFile(filePath)) {
                        for (const auto& ed : sortedEdits) {
                            if (ed.startLine < diskBuf.GetLineCount() && ed.startLine == ed.endLine) {
                                std::wstring ln = diskBuf.GetLine(ed.startLine);
                                size_t sc = (std::min)(ed.startCol, ln.length());
                                size_t ec = (std::min)(ed.endCol, ln.length());
                                diskBuf.SetLine(ed.startLine, ln.substr(0, sc) + ed.newText + ln.substr(ec));
                                editsApplied++;
                            }
                        }
                        if (diskBuf.SaveToFile(filePath)) filesTouched++;
                    }
                }
            }
            m_editor.CloseRenameWidget();
            RefreshActiveDocOutlineAndBreadcrumbs();
            m_editor.ShowRefactorPopup(L"Renamed \"" + oldName + L"\" -> \"" + newName + L"\" (" +
                                       std::to_wstring(editsApplied) + L" edits in " + std::to_wstring(filesTouched) + L" file(s))");
            InvalidateRect(m_hwnd, nullptr, FALSE);
            return;
        }
    }

    std::wstring wsRoot = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L"";
    auto snaps = CollectOpenDocSnapshots(m_editorGroups);
    auto plan = editor::BuildStaticRenamePlan(oldName, newName, wsRoot, m_drawer.GetIgnoreEngine(), snaps);
    if (!plan.valid) {
        m_editor.ShowRefactorPopup(plan.errorMessage.empty() ? L"Invalid identifier name" : plan.errorMessage);
        InvalidateRect(m_hwnd, nullptr, FALSE);
        return;
    }

    for (const auto& fg : plan.fileGroups) {
        std::wstring key = normKey(fg.filePath);
        bool matchedOpen = false;
        for (auto& grp : m_editorGroups) {
            for (auto& d : grp.docs) {
                if (d.isSpecialView || d.isUnsupportedBinary) continue;
                std::wstring dk = d.filePath.empty() ? d.fileName : d.filePath;
                if (normKey(dk) != key) continue;
                bool pushed = false;
                for (size_t li = 0; li < d.buffer.GetLineCount(); ++li) {
                    std::wstring ln = d.buffer.GetLine(li);
                    if (editor::ReplaceInLine(ln, oldName, newName, true, true, false, false)) {
                        if (!pushed) {
                            d.buffer.PushUndo();
                            pushed = true;
                        }
                        d.buffer.SetLine(li, ln);
                    }
                }
                if (pushed) {
                    MarkDocumentModified(&d);
                    matchedOpen = true;
                }
            }
        }
        if (matchedOpen) {
            filesTouched++;
            editsApplied += fg.edits.size();
        } else if (!fg.filePath.empty()) {
            editor::Buffer diskBuf;
            if (diskBuf.LoadFromFile(fg.filePath)) {
                bool changed = false;
                for (size_t li = 0; li < diskBuf.GetLineCount(); ++li) {
                    std::wstring ln = diskBuf.GetLine(li);
                    if (editor::ReplaceInLine(ln, oldName, newName, true, true, false, false)) {
                        diskBuf.SetLine(li, ln);
                        changed = true;
                    }
                }
                if (changed && diskBuf.SaveToFile(fg.filePath)) {
                    filesTouched++;
                    editsApplied += fg.edits.size();
                }
            }
        }
    }

    m_editor.CloseRenameWidget();
    if (m_drawer.HasOpenFolder()) {
        m_symbolIndex.RebuildAsync(m_drawer.GetOpenFolderPath(), &m_drawer.GetIgnoreEngine());
    }
    RefreshActiveDocOutlineAndBreadcrumbs();
    m_editor.ShowRefactorPopup(L"Renamed \"" + oldName + L"\" -> \"" + newName + L"\" (" +
                               std::to_wstring(editsApplied) + L" edits in " + std::to_wstring(filesTouched) + L" file(s))");
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

bool Window::IsFileInDirectory(const std::wstring& filePath, const std::wstring& dirPath) {
    if (filePath.empty() || dirPath.empty()) return false;
    std::wstring fNorm = filePath;
    std::wstring dNorm = dirPath;
    for (auto& c : fNorm) { if (c == L'/') c = L'\\'; c = static_cast<wchar_t>(towlower(c)); }
    for (auto& c : dNorm) { if (c == L'/') c = L'\\'; c = static_cast<wchar_t>(towlower(c)); }
    while (!dNorm.empty() && dNorm.back() == L'\\') dNorm.pop_back();
    if (fNorm.rfind(dNorm + L'\\', 0) == 0 || fNorm == dNorm) {
        return true;
    }
    return false;
}

std::wstring Window::FindProjectRootForFile(const std::wstring& filePath) const {
    std::wstring openFolder = m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : m_workspace.GetRootPath().wstring();
    if (filePath.empty()) {
        return openFolder;
    }

    std::filesystem::path cur = std::filesystem::path(filePath);
    std::error_code ec;
    if (!std::filesystem::is_directory(cur, ec)) {
        cur = cur.parent_path();
    }

    std::filesystem::path stopPath;
    if (!openFolder.empty()) {
        stopPath = std::filesystem::weakly_canonical(openFolder, ec);
    }

    std::filesystem::path bestRoot;
    std::filesystem::path p = cur;
    while (!p.empty() && p.has_relative_path()) {
        if (std::filesystem::exists(p / L"package.json", ec) ||
            std::filesystem::exists(p / L"electron.vite.config.ts", ec) ||
            std::filesystem::exists(p / L"electron.vite.config.js", ec) ||
            std::filesystem::exists(p / L"vite.config.ts", ec) ||
            std::filesystem::exists(p / L"vite.config.js", ec) ||
            std::filesystem::exists(p / L"next.config.js", ec) ||
            std::filesystem::exists(p / L"next.config.mjs", ec) ||
            std::filesystem::exists(p / L"next.config.ts", ec) ||
            std::filesystem::exists(p / L"manage.py", ec) ||
            std::filesystem::exists(p / L"composer.json", ec)) {
            bestRoot = p;
            break;
        }

        if (!stopPath.empty() && std::filesystem::equivalent(p, stopPath, ec)) {
            bestRoot = p;
            break;
        }

        std::filesystem::path parent = p.parent_path();
        if (parent == p) break;
        p = parent;
    }

    if (!bestRoot.empty()) {
        return bestRoot.wstring();
    }
    if (!openFolder.empty()) {
        return openFolder;
    }
    return cur.wstring();
}

Window::ProjectDecision Window::DetectFramework(const std::wstring& rootDir, const std::wstring& activeFilePath) {
    // 1. High-speed Decision Tree Cache Lookup with Timestamp Validation
    std::wstring key = rootDir;
    for (auto& c : key) c = static_cast<wchar_t>(towlower(c));

    auto it = m_projectDecisionCache.find(key);
    if (it != m_projectDecisionCache.end() && !it->second.markerPath.empty()) {
        std::error_code ec;
        if (std::filesystem::exists(it->second.markerPath, ec)) {
            auto curTime = std::filesystem::last_write_time(it->second.markerPath, ec);
            if (!ec && curTime == it->second.markerTime) {
                return it->second;
            }
        }
    }

    // 2. Decision Tree Evaluation
    ProjectDecision decision;
    decision.rootDir = rootDir;
    decision.framework = ProjectFramework::None;

    {
        phide::plugin::PluginFrameworkDetector customFw;
        std::wstring customMarkerPath;
        if (phide::plugin::PluginManager::Instance().TryDetectFramework(rootDir, activeFilePath, customFw, customMarkerPath)) {
            decision.framework = (customFw.port > 0) ? ProjectFramework::Vite : ProjectFramework::PythonScript;
            decision.title = customFw.title.empty() ? customFw.id : customFw.title;
            decision.command = customFw.command;
            decision.port = customFw.port;
            decision.customUrl = customFw.customUrl;
            decision.markerPath = customMarkerPath;
            return decision;
        }
    }

    std::error_code ec;
    std::filesystem::path root(rootDir);

    if (!rootDir.empty() && std::filesystem::exists(root, ec) && std::filesystem::is_directory(root, ec)) {
        // Feature Node 1: package.json (Vite, Electron, Next.js, etc.)
        std::filesystem::path pkgPath = root / L"package.json";
        if (std::filesystem::exists(pkgPath, ec)) {
            decision.markerPath = pkgPath.wstring();
            decision.markerTime = std::filesystem::last_write_time(pkgPath, ec);

            std::string pkgContent;
            {
                std::ifstream f(pkgPath, std::ios::binary);
                if (f.is_open()) {
                    std::stringstream buffer;
                    buffer << f.rdbuf();
                    pkgContent = buffer.str();
                }
            }

            auto hasDep = [&](const std::string& name) -> bool {
                return pkgContent.find("\"" + name + "\"") != std::string::npos;
            };

            // Decision Branch 1A: Electron / Electron-Vite
            bool hasElectronViteConfig = std::filesystem::exists(root / L"electron.vite.config.ts", ec) ||
                                         std::filesystem::exists(root / L"electron.vite.config.js", ec) ||
                                         std::filesystem::exists(root / L"electron.vite.config.mjs", ec);
            bool hasElectronBuilder = std::filesystem::exists(root / L"electron-builder.yml", ec) ||
                                      std::filesystem::exists(root / L"electron-builder.json", ec);
            bool hasElectron = hasDep("electron") || hasDep("electron-vite") || hasElectronViteConfig || hasElectronBuilder;

            if (hasElectron) {
                decision.framework = ProjectFramework::Electron;
                decision.title = L"Electron Server";
                if (hasElectronViteConfig || hasDep("electron-vite")) {
                    decision.command = L"npm run dev";
                } else if (pkgContent.find("\"start\"") != std::string::npos) {
                    decision.command = L"npm run start";
                } else if (pkgContent.find("\"dev\"") != std::string::npos) {
                    decision.command = L"npm run dev";
                } else {
                    decision.command = L"npm start";
                }
                decision.port = 0;
                decision.customUrl = L"";
                m_projectDecisionCache[key] = decision;
                return decision;
            }

            // Decision Branch 1B: Next.js
            bool hasNextConfig = std::filesystem::exists(root / L"next.config.js", ec) ||
                                 std::filesystem::exists(root / L"next.config.mjs", ec) ||
                                 std::filesystem::exists(root / L"next.config.ts", ec) ||
                                 std::filesystem::exists(root / L"next.config.cjs", ec) ||
                                 std::filesystem::exists(root / L".next", ec);
            if (hasNextConfig || hasDep("next")) {
                decision.framework = ProjectFramework::NextJs;
                decision.title = L"Next.js Server";
                decision.command = L"npm run dev";
                decision.port = 3000;
                decision.customUrl = L"http://localhost:3000";
                m_projectDecisionCache[key] = decision;
                return decision;
            }

            // Decision Branch 1C: Vite
            bool hasViteConfig = std::filesystem::exists(root / L"vite.config.ts", ec) ||
                                 std::filesystem::exists(root / L"vite.config.js", ec) ||
                                 std::filesystem::exists(root / L"vite.config.mjs", ec) ||
                                 std::filesystem::exists(root / L"vite.config.cjs", ec);
            if (hasViteConfig || hasDep("vite")) {
                decision.framework = ProjectFramework::Vite;
                decision.title = L"Vite Server";
                decision.command = L"npm run dev";
                decision.port = 5173;
                decision.customUrl = L"http://localhost:5173";
                m_projectDecisionCache[key] = decision;
                return decision;
            }

            // Decision Branch 1D: Astro / Nuxt
            if (std::filesystem::exists(root / L"astro.config.mjs", ec) || std::filesystem::exists(root / L"astro.config.ts", ec) || hasDep("astro")) {
                decision.framework = ProjectFramework::Vite;
                decision.title = L"Astro Server";
                decision.command = L"npm run dev";
                decision.port = 4321;
                decision.customUrl = L"http://localhost:4321";
                m_projectDecisionCache[key] = decision;
                return decision;
            }
            if (std::filesystem::exists(root / L"nuxt.config.ts", ec) || std::filesystem::exists(root / L"nuxt.config.js", ec) || hasDep("nuxt")) {
                decision.framework = ProjectFramework::Vite;
                decision.title = L"Nuxt Server";
                decision.command = L"npm run dev";
                decision.port = 3000;
                decision.customUrl = L"http://localhost:3000";
                m_projectDecisionCache[key] = decision;
                return decision;
            }

            // Decision Branch 1E: Generic Node.js with package.json
            decision.framework = ProjectFramework::NodeScript;
            decision.title = L"Node.js App";
            if (pkgContent.find("\"dev\"") != std::string::npos) {
                decision.command = L"npm run dev";
            } else if (pkgContent.find("\"start\"") != std::string::npos) {
                decision.command = L"npm start";
            } else {
                decision.command = L"npm test";
            }
            decision.port = 0;
            decision.customUrl = L"";
            m_projectDecisionCache[key] = decision;
            return decision;
        }

        // Feature Node 2: Django (manage.py)
        std::filesystem::path managePy = root / L"manage.py";
        if (std::filesystem::exists(managePy, ec)) {
            decision.markerPath = managePy.wstring();
            decision.markerTime = std::filesystem::last_write_time(managePy, ec);
            decision.framework = ProjectFramework::Django;
            decision.title = L"Django Server";
            decision.command = L"python manage.py runserver";
            decision.port = 8000;
            decision.customUrl = L"http://127.0.0.1:8000";
            m_projectDecisionCache[key] = decision;
            return decision;
        }

        // Feature Node 3: PHP Check (composer.json or index.php)
        std::filesystem::path composerJson = root / L"composer.json";
        std::filesystem::path indexPhp = root / L"index.php";
        if (std::filesystem::exists(composerJson, ec) || std::filesystem::exists(indexPhp, ec)) {
            decision.framework = ProjectFramework::Php;
            decision.title = L"PHP";
            decision.command = L"";
            m_projectDecisionCache[key] = decision;
            return decision;
        }

        // Feature Node 4: Static HTML
        std::filesystem::path indexHtml = root / L"index.html";
        if (std::filesystem::exists(indexHtml, ec)) {
            decision.framework = ProjectFramework::LiveServerHtml;
            decision.title = L"Live Server";
            decision.command = L"";
            decision.port = 5500;
            decision.customUrl = L"http://127.0.0.1:5500";
            m_projectDecisionCache[key] = decision;
            return decision;
        }
    }

    // Feature Node 5: Standalone single-file fallback based on active file extension
    std::filesystem::path p(activeFilePath);
    std::wstring ext = p.extension().wstring();
    for (auto& c : ext) c = static_cast<wchar_t>(towlower(c));

    if (ext == L".php" || ext == L".phtml" || ext == L".php8") {
        decision.framework = ProjectFramework::Php;
        decision.title = L"PHP";
        decision.command = L"";
    } else if (ext == L".py") {
        decision.framework = ProjectFramework::PythonScript;
        decision.title = L"Python Script";
        decision.command = L"python \"" + activeFilePath + L"\"";
    } else if (ext == L".html" || ext == L".htm") {
        decision.framework = ProjectFramework::LiveServerHtml;
        decision.title = L"Live Server";
        decision.port = 5500;
        decision.customUrl = L"http://127.0.0.1:5500";
    } else if (ext == L".js" || ext == L".ts" || ext == L".mjs" || ext == L".cjs") {
        decision.framework = ProjectFramework::NodeScript;
        decision.title = L"Node.js Script";
        decision.command = L"node \"" + activeFilePath + L"\"";
    }

    return decision;
}

static void KillProcessTree(DWORD rootPid) {
    if (rootPid == 0) return;
    std::vector<DWORD> toKill;
    std::unordered_set<DWORD> visited;
    toKill.push_back(rootPid);
    visited.insert(rootPid);

    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hSnap != INVALID_HANDLE_VALUE) {
        PROCESSENTRY32W pe{};
        pe.dwSize = sizeof(pe);
        std::vector<std::pair<DWORD, DWORD>> allProcs;
        if (Process32FirstW(hSnap, &pe)) {
            do {
                if (pe.th32ProcessID != 0) {
                    allProcs.emplace_back(pe.th32ProcessID, pe.th32ParentProcessID);
                }
            } while (Process32NextW(hSnap, &pe));
        }
        CloseHandle(hSnap);

        size_t head = 0;
        while (head < toKill.size()) {
            DWORD currentParent = toKill[head++];
            for (const auto& proc : allProcs) {
                if (proc.second == currentParent && proc.first != currentParent) {
                    if (visited.insert(proc.first).second) {
                        toKill.push_back(proc.first);
                    }
                }
            }
        }
    }

    for (auto it = toKill.rbegin(); it != toKill.rend(); ++it) {
        HANDLE hProc = OpenProcess(PROCESS_TERMINATE, FALSE, *it);
        if (hProc) {
            TerminateProcess(hProc, 0);
            CloseHandle(hProc);
        }
    }
}

static void CleanupPortProcessesAsync(int port) {
    if (port <= 0) return;
    std::thread([port]() {
        // Pure Win32 TCP listener inspection & kill: ZERO powershell.exe, ZERO popping console windows!
        DWORD dwSize = 0;
        GetExtendedTcpTable(NULL, &dwSize, FALSE, AF_INET, TCP_TABLE_OWNER_PID_ALL, 0);
        if (dwSize > 0) {
            std::vector<BYTE> buffer(dwSize);
            if (GetExtendedTcpTable(buffer.data(), &dwSize, FALSE, AF_INET, TCP_TABLE_OWNER_PID_ALL, 0) == NO_ERROR) {
                auto* table = reinterpret_cast<MIB_TCPTABLE_OWNER_PID*>(buffer.data());
                DWORD netPort = htons(static_cast<u_short>(port));
                for (DWORD i = 0; i < table->dwNumEntries; ++i) {
                    if (table->table[i].dwLocalPort == netPort || table->table[i].dwLocalPort == static_cast<DWORD>(port)) {
                        DWORD pid = table->table[i].dwOwningPid;
                        if (pid > 4 && pid != GetCurrentProcessId()) {
                            KillProcessTree(pid);
                        }
                    }
                }
            }
        }
    }).detach();
}

void Window::RunProjectDevServer(const std::wstring& projectRoot, const ProjectDecision& decision) {
    // 1. Terminate any previous server session for this root to prevent process leaks
    m_terminal.TerminateServerSession(projectRoot);
    StopLiveServer(projectRoot, /*closeTab=*/false);

    // 2. Check if another non-Phide process owns the requested dev port before launching
    if (decision.port > 0) {
        if (!CheckPortBeforeServerStart(decision.port, decision.title, nullptr,
                [this, projectRoot, decision](int chosenPort) {
                    ProjectDecision updated = decision;
                    if (chosenPort != updated.port) {
                        std::wstring oldPortStr = std::to_wstring(updated.port);
                        std::wstring newPortStr = std::to_wstring(chosenPort);
                        updated.port = chosenPort;
                        size_t urlPos = updated.customUrl.find(L":" + oldPortStr);
                        if (urlPos != std::wstring::npos) {
                            updated.customUrl.replace(urlPos + 1, oldPortStr.length(), newPortStr);
                        }
                        if (!updated.command.empty()) {
                            updated.command = L"set PORT=" + newPortStr + L" && " + updated.command;
                        }
                    }
                    RunProjectDevServer(projectRoot, updated);
                })) {
            return;
        }
    }

    m_isProjectRunning = true;
    m_runningProjectRoot = projectRoot;
    m_runningProjectDecision = decision;

    auto* srv = FindLiveServer(projectRoot);
    if (!srv) {
        ActiveLiveServer entry;
        entry.filePath = projectRoot;
        entry.fileName = std::filesystem::path(projectRoot).filename().wstring();
        entry.rootDir = projectRoot;
        entry.port = decision.port;
        entry.framework = decision.title;
        entry.title = decision.title;
        entry.customUrl = decision.customUrl;
        entry.progress = 0.05f;
        entry.progressDurationMs = 2200.0f;
        entry.elapsedMs = 0.0f;
        entry.browserOpened = false;
        entry.isStarting = true;
        entry.waitForTerminalReady = true;
        entry.hasError = false;
        entry.errorMsg.clear();
        m_activeLiveServers.push_back(std::move(entry));
    } else {
        srv->framework = decision.title;
        srv->title = decision.title;
        srv->customUrl = decision.customUrl;
        srv->port = decision.port;
        srv->progress = 0.05f;
        srv->elapsedMs = 0.0f;
        srv->isStarting = true;
        srv->waitForTerminalReady = true;
        srv->browserOpened = false;
        srv->hasError = false;
        srv->errorMsg.clear();
    }

    m_terminal.Open(projectRoot);
    AnimateTerminalOpen();
    m_terminal.StartServerSession(decision.title, decision.command, projectRoot, projectRoot);
    m_isTerminalFocused = false;
    if (HWND animHwnd = GetMainPostHwnd()) SetTimer(animHwnd, m_animTimerId, 16, nullptr);
    UpdateExecutionButtonStates();
    InvalidateRect(m_hwnd, nullptr, FALSE);
}

