                        break;

                    // Editor Layout Submenu Actions (Image 3)
                    case ui::MenuActionId::ToggleLineNumbers:
                        m_config.showLineNumbers = !m_config.showLineNumbers;
                        InvalidateRect(m_hwnd, nullptr, FALSE);
                        break;
                    case ui::MenuActionId::GraphToggleColored:
                        m_config.isGraphColored = !m_config.isGraphColored;
                        InvalidateRect(m_hwnd, nullptr, FALSE);
                        break;
                    case ui::MenuActionId::ToggleMarkdownPreview:
                        ToggleMarkdownPreview();
                        break;
                    case ui::MenuActionId::ToggleCodeLens:
                        ToggleCodeLens();
                        break;
                    case ui::MenuActionId::ToggleErrorLens:
                        ToggleErrorLens();
                        break;
                    case ui::MenuActionId::ToggleGutterBlame:
                        ToggleGutterBlame();
                        break;
                    case ui::MenuActionId::LayoutSingle:
                        SetEditorSplitLayout(editor::EditorSplitLayout::Single);
                        break;
                    case ui::MenuActionId::LayoutTwoColumns:
                    case ui::MenuActionId::LayoutSplitRight:
                    case ui::MenuActionId::LayoutSplitLeft:
                        if (m_editorGroups.size() <= 1) {
                            SetEditorSplitLayout(editor::EditorSplitLayout::TwoColumns);
                        } else if (action == ui::MenuActionId::LayoutTwoColumns) {
                            SetEditorSplitLayout(editor::EditorSplitLayout::TwoColumns);
                        } else {
                            SplitEditor();
                        }
                        break;
                    case ui::MenuActionId::LayoutThreeColumns:
                        SetEditorSplitLayout(editor::EditorSplitLayout::ThreeColumns);
                        break;
                    case ui::MenuActionId::LayoutTwoRows:
                    case ui::MenuActionId::LayoutSplitDown:
                    case ui::MenuActionId::LayoutSplitUp:
                        if (m_editorGroups.size() <= 1 || action == ui::MenuActionId::LayoutTwoRows) {
                            SetEditorSplitLayout(editor::EditorSplitLayout::TwoRows);
                        } else if (m_editorGroups.size() == 2 && m_splitState.layout == editor::EditorSplitLayout::TwoColumns) {
                            SetEditorSplitLayout(m_focusedGroupIdx == 0
                                ? editor::EditorSplitLayout::LeftSplitRightFull
                                : editor::EditorSplitLayout::LeftFullRightSplit);
                        } else {
                            SetEditorSplitLayout(editor::EditorSplitLayout::Grid2x2);
                        }
                        break;
                    case ui::MenuActionId::LayoutThreeRows:
                        SetEditorSplitLayout(editor::EditorSplitLayout::ThreeRows);
                        break;
                    case ui::MenuActionId::LayoutGrid2x2:
                        SetEditorSplitLayout(editor::EditorSplitLayout::Grid2x2);
                        break;
                    case ui::MenuActionId::LayoutTwoRowsLeft:
                    case ui::MenuActionId::LayoutSplitInGroup:
                        SetEditorSplitLayout(editor::EditorSplitLayout::LeftSplitRightFull);
                        break;
                    case ui::MenuActionId::LayoutTwoRowsRight:
                        SetEditorSplitLayout(editor::EditorSplitLayout::LeftFullRightSplit);
                        break;
                    case ui::MenuActionId::LayoutTwoColumnsBottom:
                        SetEditorSplitLayout(editor::EditorSplitLayout::TopFullBottomSplit);
                        break;
                    case ui::MenuActionId::LayoutFlip:
                        if (m_editorGroups.size() == 2) {
                            SetEditorSplitLayout(m_splitState.layout == editor::EditorSplitLayout::TwoColumns
                                ? editor::EditorSplitLayout::TwoRows
                                : editor::EditorSplitLayout::TwoColumns);
                        } else if (m_editorGroups.size() == 3) {
                            if (m_splitState.layout == editor::EditorSplitLayout::LeftSplitRightFull) {
                                SetEditorSplitLayout(editor::EditorSplitLayout::LeftFullRightSplit);
                            } else if (m_splitState.layout == editor::EditorSplitLayout::LeftFullRightSplit) {
                                SetEditorSplitLayout(editor::EditorSplitLayout::LeftSplitRightFull);
                            } else {
                                std::reverse(m_editorGroups.begin(), m_editorGroups.end());
                                m_focusedGroupIdx = static_cast<int>(m_editorGroups.size() - 1 - m_focusedGroupIdx);
                                UpdateEditorGroupBounds();
                            }
                        } else if (m_editorGroups.size() > 1) {
                            std::reverse(m_editorGroups.begin(), m_editorGroups.end());
                            m_focusedGroupIdx = static_cast<int>(m_editorGroups.size() - 1 - m_focusedGroupIdx);
                            UpdateEditorGroupBounds();
                        }
                        break;
                    case ui::MenuActionId::LayoutMoveNewWindow:
                    case ui::MenuActionId::LayoutCopyNewWindow: {
                        int activeIdx = (m_focusedGroupIdx >= 0 && m_focusedGroupIdx < static_cast<int>(m_editorGroups.size()))
                                      ? m_editorGroups[m_focusedGroupIdx].activeDocIdx : -1;
                        if (activeIdx >= 0) {
                            if (action == ui::MenuActionId::LayoutMoveNewWindow) {
                                if (m_activeFloatingWindow) {
                                    PendingFloatingAction act{};
                                    act.kind = PendingFloatingAction::Kind::DockAllEditorToMain;
                                    act.winId = m_activeFloatingWindow->id;
                                    m_pendingFloatingActions.push_back(act);
                                    if (HWND postHwnd = GetMainPostHwnd()) PostMessageW(postHwnd, WM_USER + 235, 0, 0);
                                } else {
                                    UndockTabToFloatingWindow(m_focusedGroupIdx, activeIdx);
                                }
                            } else {
                                DetachEditorToNewWindow(m_focusedGroupIdx, activeIdx, false);
                            }
                        } else {
                            DoNewWindow();
                        }
                        break;
                    }

                    // Context Menu Actions (Images 4 & 5)
                    case ui::MenuActionId::CtxOpenToSide: {
                        auto targets = GetActiveExplorerTargetPaths(m_contextTargetPath);
                        for (const auto& t : targets) {
                            std::error_code ec;
                            if (!t.empty() && !std::filesystem::is_directory(t, ec)) {
                                OpenFileDocument(t, false);
                            }
                        }
                        break;
                    }
                    case ui::MenuActionId::CtxOpenWith:
                        if (!m_contextTargetPath.empty()) {
                            ShellExecuteW(m_hwnd, L"open", L"rundll32.exe",
                                         (L"shell32.dll,OpenAs_RunDLL " + m_contextTargetPath).c_str(),
                                         nullptr, SW_SHOWNORMAL);
                        }
                        break;
                    case ui::MenuActionId::CtxRevealInExplorer:
                        if (!m_contextTargetPath.empty()) {
                            std::wstring param = L"/select,\"" + m_contextTargetPath + L"\"";
                            ShellExecuteW(nullptr, L"open", L"explorer.exe", param.c_str(), nullptr, SW_SHOWNORMAL);
                        }
                        break;
                    case ui::MenuActionId::CtxOpenInTerminal:
                        if (!m_contextTargetPath.empty()) {
                            std::wstring dir = m_contextTargetIsFolder ? m_contextTargetPath
                                : std::filesystem::path(m_contextTargetPath).parent_path().wstring();
                            ShellExecuteW(nullptr, L"open", L"cmd.exe", nullptr, dir.empty() ? nullptr : dir.c_str(), SW_SHOWNORMAL);
                        }
                        break;
                    case ui::MenuActionId::CtxCompareWithSelected:
                        if (!m_compareSourcePath.empty() && std::filesystem::exists(m_compareSourcePath)) {
                            OpenCompareFilesDiffDocument(m_compareSourcePath, m_contextTargetPath);
                        } else {
                            m_compareSourcePath = m_contextTargetPath;
                        }
                        break;
                    case ui::MenuActionId::CtxSelectForCompare:
                        m_compareSourcePath = m_contextTargetPath;
                        break;
                    case ui::MenuActionId::CtxUndo:
                        DoExplorerUndo();
                        break;
                    case ui::MenuActionId::CtxRedo:
                        DoExplorerRedo();
                        break;
                    case ui::MenuActionId::CtxCut:
                        CopyExplorerSelectionToClipboard(true, m_contextTargetPath);
                        break;
                    case ui::MenuActionId::CtxCopy:
                        CopyExplorerSelectionToClipboard(false, m_contextTargetPath);
                        break;
                    case ui::MenuActionId::CtxPaste:
                        PasteClipboardToExplorerTarget(m_contextTargetPath, m_contextTargetIsFolder);
                        break;
                    case ui::MenuActionId::CtxCopyPath: {
                        auto targets = GetActiveExplorerTargetPaths(m_contextTargetPath);
                        if (!targets.empty()) {
                            std::wstring joined;
                            for (size_t i = 0; i < targets.size(); ++i) {
                                if (i > 0) joined += L"\r\n";
                                joined += targets[i];
                            }
                            SetClipboardText(m_hwnd, joined);
                        }
                        break;
                    }
                    case ui::MenuActionId::CtxCopyRelativePath: {
                        auto targets = GetActiveExplorerTargetPaths(m_contextTargetPath);
                        if (!targets.empty()) {
                            std::wstring joined;
                            const std::wstring root = m_drawer.GetOpenFolderPath();
                            for (size_t i = 0; i < targets.size(); ++i) {
                                if (i > 0) joined += L"\r\n";
                                joined += GetRelativePath(targets[i], root);
                            }
                            SetClipboardText(m_hwnd, joined);
                        }
                        break;
                    }
                    case ui::MenuActionId::CtxRename:
                        if (!m_contextTargetPath.empty()) {
                            m_isTerminalFocused = false;
                            m_drawer.StartInlineRenameByPath(m_contextTargetPath);
                            InvalidateRect(m_hwnd, nullptr, FALSE);
                        }
                        break;
                    case ui::MenuActionId::CtxDelete: {
                        auto targets = GetActiveExplorerTargetPaths(m_contextTargetPath);
                        std::vector<std::wstring> existing;
                        std::error_code ec;
                        for (const auto& t : targets) {
                            if (!t.empty() && std::filesystem::exists(t, ec)) existing.push_back(t);
                        }
                        if (existing.size() > 1) {
                            m_confirmDiscardModal.OpenDeleteBatch(existing);
                            InvalidateRect(m_hwnd, nullptr, FALSE);
                        } else if (!existing.empty()) {
                            bool isFolder = std::filesystem::is_directory(existing.front(), ec);
                            m_confirmDiscardModal.OpenDelete(existing.front(), isFolder);
                            InvalidateRect(m_hwnd, nullptr, FALSE);
                        }
                        break;
                    }
                    case ui::MenuActionId::CtxGitStage:
                    case ui::MenuActionId::CtxGitUnstage: {
                        const bool doStage = (action == ui::MenuActionId::CtxGitStage);
                        if (m_drawer.IsGitRepo() && m_drawer.HasOpenFolder()) {
                            auto targets = GetActiveExplorerTargetPaths(m_contextTargetPath);
                            const std::wstring root = m_drawer.GetOpenFolderPath();
                            std::vector<std::wstring> relPaths;
                            relPaths.reserve(targets.size());
                            for (const auto& t : targets) {
                                std::wstring rel = GetRelativePath(t, root);
                                if (!rel.empty()) relPaths.push_back(std::move(rel));
                            }
                            if (!relPaths.empty()) {
                                m_drawer.StageFilesBatchAsync(relPaths, doStage);
                            }
                        }
                        break;
                    }
                    case ui::MenuActionId::CtxNewFile: {
                        std::wstring parentDir = m_contextTargetIsFolder ? m_contextTargetPath
                            : (m_contextTargetPath.empty() ? (m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L".")
                                                           : std::filesystem::path(m_contextTargetPath).parent_path().wstring());
                        m_drawer.StartInlineCreate(parentDir, false);
                        InvalidateRect(m_hwnd, nullptr, FALSE);
                        break;
                    }
                    case ui::MenuActionId::CtxNewFolder: {
                        std::wstring parentDir = m_contextTargetIsFolder ? m_contextTargetPath
                            : (m_contextTargetPath.empty() ? (m_drawer.HasOpenFolder() ? m_drawer.GetOpenFolderPath() : L".")
                                                           : std::filesystem::path(m_contextTargetPath).parent_path().wstring());
                        m_drawer.StartInlineCreate(parentDir, true);
                        InvalidateRect(m_hwnd, nullptr, FALSE);
                        break;
                    }
                    case ui::MenuActionId::CtxFindInFolder:
                        DoShowSearch();
                        break;

                    // Top Edit Menu Actions (User Request & Image 5)
                    case ui::MenuActionId::EditUndo:
                        DoUndo();
